-- Schema for Domain: regulatory | Business: Power and Utilities | Version: v1_mvm
-- Generated on: 2026-04-29 23:12:57

-- ========= DATABASE =========
CREATE DATABASE IF NOT EXISTS `power_and_utilities`.`regulatory` COMMENT 'Manages all compliance obligations, tariff filings, rate cases, CPCN applications, IRP submissions, and regulatory reporting to PUCs, FERC, NERC, and EPA. Tracks dockets, testimony, prudency reviews, performance-based ratemaking (PBR), GHG/emissions compliance records, and cost recovery mechanisms including FAC and AFUDC. Ensures adherence to all jurisdictional requirements.';

-- ========= TABLES =========
CREATE OR REPLACE TABLE `power_and_utilities`.`regulatory`.`docket` (
    `docket_id` BIGINT COMMENT 'Unique surrogate identifier for each regulatory docket or proceeding record in the lakehouse Silver layer. Primary key for this entity.',
    `appeal_deadline_date` DATE COMMENT 'The deadline by which a party must file a request for rehearing, appeal, or petition for review of the final order. Calculated from the final order date based on applicable statutory or regulatory timelines (e.g., 30 days for FERC rehearing requests under FPA Section 313). Null if no final order has been issued.',
    `appeal_filed` BOOLEAN COMMENT 'Indicates whether the utility or any party has filed an appeal, request for rehearing, or petition for review of the final order in this docket. True if an appeal or rehearing request has been filed; False otherwise. Null if the docket has not yet reached a final order. Used to track post-order litigation exposure and contingent liability.',
    `approved_rate_of_return` DECIMAL(18,2) COMMENT 'The overall rate of return on equity (ROE) approved by the regulatory authority in the final order, expressed as a decimal (e.g., 0.0975 for 9.75%). Null until a final order is issued or if the proceeding is not a rate case. Critical for financial planning, EBITDA projections, and investor reporting.',
    `approved_revenue_requirement` DECIMAL(18,2) COMMENT 'The total annual revenue requirement approved by the regulatory authority in the final order for a rate case, expressed in U.S. dollars. Null until a final order is issued or if the proceeding is not a rate case. Used for rate design, billing system updates, and financial reporting under GAAP and SOX.',
    `case_manager` STRING COMMENT 'Full name of the regulatory affairs case manager or project manager responsible for coordinating the utilitys internal response, testimony preparation, and milestone tracking for this docket. Typically a regulatory affairs department employee.',
    `close_date` DATE COMMENT 'The date on which the regulatory authority formally closed the docket, typically upon issuance of a final order, dismissal, or withdrawal. Null if the docket remains open or active. Used to calculate proceeding duration and track regulatory cycle times.',
    `confidential_flag` BOOLEAN COMMENT 'Indicates whether the utility has requested confidential treatment for some or all documents filed in this docket under applicable protective order or FOIA exemption. True if confidential treatment has been requested; False if all filings are public. Used to enforce data access controls and document management policies.',
    `cpcn_project_name` STRING COMMENT 'The name of the capital project or infrastructure investment for which a Certificate of Public Convenience and Necessity (CPCN) is being sought. Applicable only to CPCN proceedings. Examples: North Substation 345kV Upgrade, Gas Pipeline Replacement Phase 2. Null for non-CPCN dockets.',
    `created_timestamp` TIMESTAMP COMMENT 'The timestamp when this docket record was first created in the regulatory case management system or data lakehouse. Represents the audit trail creation event. Formatted as yyyy-MM-ddTHH:mm:ss.SSSXXX per enterprise data standards.',
    `customer_class_scope` STRING COMMENT 'Identifies the customer class(es) affected by this regulatory proceeding. For rate cases and tariff filings, indicates whether the proceeding impacts residential, commercial, industrial, or all customer classes. none is used for proceedings that do not directly affect customer rates (e.g., NERC reliability compliance).. Valid values are `residential|commercial|industrial|all|none`',
    `docket_number` STRING COMMENT 'The official externally-assigned docket or case number issued by the jurisdictional authority (e.g., PUC, FERC, NERC, EPA). This is the primary business identifier used in all regulatory correspondence, filings, and orders. Examples: FERC Docket No. ER24-1234, PUC Case No. 24-0001-EL-RDR.',
    `docket_status` STRING COMMENT 'Current lifecycle status of the regulatory docket or proceeding. open indicates the docket has been initiated but no active proceedings are underway; active indicates proceedings are actively ongoing; suspended indicates proceedings are temporarily halted by order or stipulation; closed indicates the proceeding has concluded with a final order or disposition; withdrawn indicates the utility voluntarily withdrew the filing.. Valid values are `open|active|suspended|closed|withdrawn`',
    `effective_date` DATE COMMENT 'The date on which the rates, tariff provisions, or regulatory requirements approved in this docket become effective and binding. For rate cases, this is the date new rates go into effect. For tariff filings, this is the tariff effective date. May be subject to refund if rates are accepted subject to refund under FERC practice.',
    `estimated_capex` DECIMAL(18,2) COMMENT 'The estimated capital expenditure (CAPEX) associated with the project or investment subject to this regulatory proceeding, expressed in U.S. dollars. Relevant for CPCN applications, IRP submissions, and major infrastructure rate cases. Used for prudency review tracking and AFUDC calculation. Null for proceedings not involving capital investment.',
    `filing_date` DATE COMMENT 'The date on which the utility filed the initial application, petition, or complaint with the regulatory authority. This is the principal business event date for the docket — the date the proceeding was formally initiated. Used for tracking regulatory deadlines, statutory timelines, and compliance milestones.',
    `final_order_date` DATE COMMENT 'The date on which the regulatory authority issued the final order, decision, or ruling concluding the proceeding. Null if the docket is still open or active. Used to calculate total proceeding duration, track regulatory cycle times, and trigger downstream actions such as billing system rate updates and financial reporting.',
    `ghg_program_ref` STRING COMMENT 'Reference to the specific GHG compliance program or emissions regulation at issue in an EPA or state environmental compliance docket (e.g., EPA Clean Air Act Section 111(d), State GHG Cap-and-Trade Program, RPS Compliance). Applicable to GHG and emissions compliance proceedings. Null for non-environmental dockets.',
    `hearing_date` DATE COMMENT 'The scheduled or actual start date of the formal evidentiary hearing before the regulatory authority or administrative law judge (ALJ). Null if no hearing is required or if the hearing has not yet been scheduled. Used for legal resource scheduling and milestone tracking.',
    `hearing_required` BOOLEAN COMMENT 'Indicates whether the regulatory authority has ordered or is expected to require a formal evidentiary hearing (trial-type proceeding) for this docket. True if a hearing has been ordered or is anticipated; False if the proceeding is expected to be resolved on the written record. Impacts resource planning for testimony preparation and witness scheduling.',
    `intervenor_count` STRING COMMENT 'The number of parties that have been granted intervenor status in the regulatory proceeding. Intervenors may include consumer advocates, industrial customers, environmental groups, competing utilities, and municipal entities. A higher intervenor count typically signals a more complex and contested proceeding. Updated as the proceeding progresses.',
    `irp_planning_horizon_years` STRING COMMENT 'The planning horizon in years covered by an Integrated Resource Plan (IRP) submission. Typically 10, 15, or 20 years. Applicable only to IRP dockets. Used to track long-range resource adequacy planning obligations and RPS compliance trajectories. Null for non-IRP proceedings.',
    `jurisdiction` STRING COMMENT 'The specific jurisdictional scope of the docket — identifies the state, federal, or regional authority. For state PUC proceedings, this is the two-letter state abbreviation (e.g., OH, CA, TX). For federal proceedings, this is FEDERAL. For regional reliability proceedings, this is the NERC region (e.g., RFC, SERC, WECC).',
    `lead_attorney` STRING COMMENT 'Full name of the lead regulatory attorney responsible for managing the utilitys legal strategy and filings in this docket. Sourced from the legal departments matter management system. Used for workload tracking, attorney assignment reporting, and legal resource planning.',
    `nerc_standard_ref` STRING COMMENT 'The specific NERC reliability standard(s) at issue in a NERC compliance investigation or reliability proceeding (e.g., FAC-001-3, CIP-007-6, TPL-001-4). Applicable only to NERC reliability and compliance dockets. Null for non-NERC proceedings. Used for NERC compliance tracking and BES reliability reporting.',
    `open_date` DATE COMMENT 'The date on which the regulatory authority formally opened or docketed the proceeding. May differ from the filing date if the authority assigns a docket number on a date subsequent to the initial filing. Marks the official commencement of the regulatory proceeding.',
    `priority_level` STRING COMMENT 'Internal priority classification assigned by the regulatory affairs department to indicate the strategic and financial significance of the docket to the utility. critical indicates proceedings with major rate impact or compliance risk; high indicates significant proceedings; medium indicates routine proceedings; low indicates minor or administrative filings. Used for resource allocation and executive reporting.. Valid values are `critical|high|medium|low`',
    `proceeding_subtype` STRING COMMENT 'Further classification within the proceeding type. For example, within a rate case: electric general rate case, gas general rate case, transmission rate case (OATT). Within tariff filings: initial tariff, tariff amendment, tariff cancellation. Provides granular categorization for reporting and analytics.',
    `proceeding_type` STRING COMMENT 'Classification of the regulatory proceeding or filing type. Defines the nature and purpose of the docket. [ENUM-REF-CANDIDATE: rate_case|cpcn|tariff_filing|irp|rulemaking|complaint|prudency_review|compliance_investigation|pbr|ghg_compliance|nerc_reliability|ppa_approval — promote to reference product]',
    `rate_case_type` STRING COMMENT 'Specifies the type of rate case proceeding. general is a full cost-of-service rate case; limited is a focused rate case on specific cost elements; formula is a rate case using a pre-approved formula rate mechanism (common in FERC transmission); pbr is a Performance-Based Ratemaking proceeding; settlement is a negotiated settlement rate case. Null for non-rate-case dockets.. Valid values are `general|limited|formula|pbr|settlement`',
    `regulatory_body` STRING COMMENT 'The jurisdictional authority or governing body with which the docket is filed or by which it is assigned. Identifies the primary regulator overseeing the proceeding. Values include FERC (Federal Energy Regulatory Commission), PUC (Public Utility Commission), NERC (North American Electric Reliability Corporation), EPA (U.S. Environmental Protection Agency), PHMSA (Pipeline and Hazardous Materials Safety Administration), DOE (U.S. Department of Energy), OSHA (Occupational Safety and Health Administration). [ENUM-REF-CANDIDATE: FERC|PUC|NERC|EPA|PHMSA|DOE|OSHA — 7 candidates stripped; promote to reference product]',
    `requested_rate_of_return` DECIMAL(18,2) COMMENT 'The overall rate of return on equity (ROE) requested by the utility in a rate case, expressed as a decimal (e.g., 0.1050 for 10.50%). Null for non-rate-case proceedings. Used in rate case analytics, benchmarking against peer utilities, and PBR performance tracking.',
    `requested_revenue_requirement` DECIMAL(18,2) COMMENT 'The total annual revenue requirement requested by the utility in a rate case filing, expressed in U.S. dollars. Represents the utilitys claimed cost of service including OPEX, CAPEX recovery (depreciation), AFUDC, taxes, and allowed return on equity (ROE). Null for non-rate-case proceedings. This is a pre-decision requested amount, not the approved amount.',
    `rto_iso_ref` STRING COMMENT 'Identifies the Regional Transmission Organization (RTO) or Independent System Operator (ISO) relevant to this docket, if applicable. Examples: PJM, MISO, CAISO, SPP, ERCOT, NYISO, ISO-NE. Relevant for FERC transmission rate cases, OATT filings, and market rule proceedings. Null for state-only or non-transmission proceedings.',
    `service_type` STRING COMMENT 'Identifies whether the docket pertains to electric service, gas service, or both. Used to route dockets to the appropriate regulatory, legal, and operations teams and to support domain-specific regulatory reporting.. Valid values are `electric|gas|both`',
    `settlement_date` DATE COMMENT 'The date on which the settlement agreement was executed or filed with the regulatory authority. Null if no settlement was reached. Used in conjunction with settlement_reached to track the timeline of negotiated resolutions and their impact on proceeding duration.',
    `settlement_reached` BOOLEAN COMMENT 'Indicates whether the parties in the regulatory proceeding reached a negotiated settlement agreement in lieu of a fully litigated final order. True if a settlement was filed and approved; False if the proceeding was fully litigated or is still pending. Used to track settlement rates and litigation complexity across the regulatory docket portfolio.',
    `statutory_deadline_date` DATE COMMENT 'The date by which the regulatory authority is legally required to issue a final order or decision under applicable statute or rule. For example, FERC has a 60-day default effective date for rate filings under FPA Section 205; state PUCs may have statutory deadlines for rate case decisions. Null if no statutory deadline applies.',
    `subject_matter_summary` STRING COMMENT 'A concise narrative description of the subject matter, issues, and relief sought in the regulatory proceeding. Provides business context for users who need to understand the docket without reviewing the full filing. Sourced from the utilitys regulatory affairs case management system or the regulatory authoritys docket management system.',
    `test_year` STRING COMMENT 'The test year or test period used as the basis for cost-of-service calculations in a rate case. May be a historical test year (e.g., 2023), a future test year (e.g., 2025), or a hybrid period (e.g., 2023-2024). Null for non-rate-case proceedings. Fundamental to rate case analytics and cost allocation studies.. Valid values are `^[0-9]{4}(-[0-9]{4})?$`',
    `updated_timestamp` TIMESTAMP COMMENT 'The timestamp when this docket record was most recently modified in the regulatory case management system or data lakehouse. Used for change data capture (CDC), ETL incremental loads, and audit trail compliance. Formatted as yyyy-MM-ddTHH:mm:ss.SSSXXX per enterprise data standards.',
    `utility_division` STRING COMMENT 'The utility operating division or service territory to which this docket primarily applies. Distinguishes between electric distribution, gas distribution, transmission, generation, or combined proceedings. Critical for segregating regulatory obligations by business unit and for rate case cost allocation.. Valid values are `electric|gas|transmission|generation|combined`',
    CONSTRAINT pk_docket PRIMARY KEY(`docket_id`)
) COMMENT 'Master record for each regulatory docket or proceeding filed with or assigned by a jurisdictional authority (PUC, FERC, NERC, EPA, PHMSA). Captures docket number, proceeding type (rate case, CPCN, tariff filing, IRP, rulemaking, complaint, prudency review, compliance investigation), filing jurisdiction, assigned regulatory body, docket status (open, active, suspended, closed), open/close dates, lead attorney, associated case manager, and key milestone dates. Serves as the SSOT anchor for all regulatory proceedings — the central hub to which rate cases, filings, orders, CPCN applications, IRP submissions, and prudency reviews connect.';

CREATE OR REPLACE TABLE `power_and_utilities`.`regulatory`.`rate_case` (
    `rate_case_id` BIGINT COMMENT 'Unique surrogate identifier for each rate case or rate proceeding record in the system. Serves as the primary key for the rate_case data product.',
    `docket_id` BIGINT COMMENT 'Reference to the parent regulatory docket under which this rate case is filed. Links the rate case to its governing docket record for full proceeding traceability.',
    `financial_period_id` BIGINT COMMENT 'Foreign key linking to finance.financial_period. Business justification: Rate cases use specific financial periods as test years for revenue requirement calculations. Finance teams extract closed period actuals for rate case cost studies. Direct period linkage enables auto',
    `afudc_rate_pct` DECIMAL(18,2) COMMENT 'Allowance for Funds Used During Construction (AFUDC) rate approved or proposed in this rate case, expressed as a percentage. AFUDC capitalizes the cost of financing construction work in progress (WIP) and is a component of rate base.',
    `approved_rate_base` DECIMAL(18,2) COMMENT 'Total rate base authorized by the regulatory authority in the final order, expressed in US dollars. Reflects any disallowances, exclusions, or adjustments made by the regulator to the utilitys requested rate base.',
    `approved_rates_effective_date` DATE COMMENT 'Date on which the final approved rates became effective for billing purposes. May differ from the final order date if the order specifies a prospective effective date or if rates are subject to a tariff filing lag.',
    `approved_revenue_requirement` DECIMAL(18,2) COMMENT 'Final annual revenue requirement authorized by the regulatory authority in the final order, expressed in US dollars. May differ from the requested amount due to regulatory adjustments, disallowances, or settlements.',
    `approved_roe_pct` DECIMAL(18,2) COMMENT 'Return on Equity (ROE) percentage authorized by the regulatory authority in the final order. The approved ROE directly determines the equity return component of the utilitys allowed revenue requirement.',
    `approved_wacc_pct` DECIMAL(18,2) COMMENT 'Weighted Average Cost of Capital (WACC) percentage authorized by the regulatory authority in the final order. Reflects the approved blended cost of debt and equity used to compute the authorized return on rate base.',
    `case_name` STRING COMMENT 'Official descriptive name or title of the rate case as filed with the regulatory authority (e.g., General Rate Case 2024 — Electric Distribution). Used for identification in regulatory filings and internal reporting.',
    `case_status` STRING COMMENT 'Current lifecycle status of the rate case proceeding. Tracks progression from initial filing through regulatory review, interim rate authorization, final order issuance, and case closure or appeal. [ENUM-REF-CANDIDATE: draft|filed|pending|suspended|interim_rates_in_effect|final_order_issued|closed|appealed — promote to reference product]',
    `case_type` STRING COMMENT 'Classification of the rate proceeding by regulatory scope and commodity. Distinguishes general rate cases from transmission-only, gas distribution, electric distribution, formula rate, or limited-scope proceedings. [ENUM-REF-CANDIDATE: general_rate_case|transmission_rate_case|gas_distribution_rate_case|electric_distribution_rate_case|formula_rate_case|limited_rate_case|cost_of_service|PBR_only — promote to reference product]. Valid values are `general_rate_case|transmission_rate_case|gas_distribution_rate_case|electric_distribution_rate_case|formula_rate_case|limited_rate_case`',
    `created_timestamp` TIMESTAMP COMMENT 'Timestamp indicating when this rate case record was first created in the system. Used for audit trail and data lineage tracking in the regulatory data product.',
    `debt_ratio_pct` DECIMAL(18,2) COMMENT 'Approved long-term debt percentage of the capital structure as authorized in the final order. Together with equity_ratio_pct defines the approved capital structure for rate-setting purposes.',
    `equity_ratio_pct` DECIMAL(18,2) COMMENT 'Approved equity percentage of the capital structure as authorized in the final order. Together with the debt ratio, defines the capital structure used to compute the weighted average cost of capital and allowed return.',
    `fac_indicator` BOOLEAN COMMENT 'Indicates whether this rate case includes or establishes a Fuel Adjustment Clause (FAC) mechanism allowing automatic pass-through of fuel cost changes between rate cases. True = FAC mechanism included; False = no FAC.',
    `filing_date` DATE COMMENT 'Calendar date on which the rate case application or tariff filing was formally submitted to the regulatory authority. Establishes the official start of the regulatory proceeding and triggers statutory review deadlines.',
    `filing_jurisdiction_state` STRING COMMENT 'Two-letter US state code identifying the state PUC jurisdiction where this rate case is filed (e.g., CA, TX, NY). Null for FERC-only proceedings.. Valid values are `^[A-Z]{2}$`',
    `final_order_date` DATE COMMENT 'Date on which the regulatory authority issued the final order concluding the rate case proceeding. Marks the official end of the adjudicatory phase and establishes the effective date for approved rates.',
    `interim_rate_effective_date` DATE COMMENT 'Date on which interim rates became effective pending the final order. Interim rates are provisional rates authorized by the regulator to allow the utility to begin collecting adjusted revenues before the proceeding concludes.',
    `interim_revenue_requirement` DECIMAL(18,2) COMMENT 'Annual revenue requirement authorized on an interim basis pending the final order, expressed in US dollars. Subject to refund or true-up adjustment once the final order is issued.',
    `notes` STRING COMMENT 'Free-text field for capturing supplementary information, regulatory conditions, compliance obligations, or material facts associated with the rate case that are not captured in structured fields (e.g., specific disallowances, conditions of approval, appeal status details).',
    `pbr_actual_value` DECIMAL(18,2) COMMENT 'Actual measured performance value achieved by the utility for the PBR metric during the measurement period. Compared against pbr_target_value to determine variance and calculate earned incentives or assessed penalties.',
    `pbr_incentive_penalty_amount` DECIMAL(18,2) COMMENT 'Dollar amount of the earned incentive (positive) or assessed penalty (negative) resulting from the PBR performance variance for the measurement period. Directly impacts the utilitys allowed revenue recovery.',
    `pbr_indicator` BOOLEAN COMMENT 'Indicates whether this rate case includes a Performance-Based Ratemaking (PBR) component with defined metrics, targets, and incentive/penalty mechanisms. True = PBR component present; False = traditional cost-of-service only.',
    `pbr_measurement_period_end` DATE COMMENT 'End date of the PBR performance measurement period. Together with pbr_measurement_period_start defines the evaluation window for PBR metric assessment.',
    `pbr_measurement_period_start` DATE COMMENT 'Start date of the PBR performance measurement period during which the utilitys actual performance is evaluated against approved targets. Populated only when pbr_indicator is True.',
    `pbr_metric_type` STRING COMMENT 'Type of PBR performance metric tracked in this rate case. Common metrics include SAIDI (System Average Interruption Duration Index), SAIFI (System Average Interruption Frequency Index), CAIDI (Customer Average Interruption Duration Index), customer satisfaction scores, renewable integration percentage, Energy Efficiency (EE) savings, and Demand Response (DR) curtailment. Populated only when pbr_indicator is True. [ENUM-REF-CANDIDATE: SAIDI|SAIFI|CAIDI|customer_satisfaction|renewable_integration_pct|EE_savings|DR_curtailment|GHG_emissions — promote to reference product]',
    `pbr_target_value` DECIMAL(18,2) COMMENT 'Approved target value for the PBR metric defined in pbr_metric_type for the measurement period. Represents the performance threshold the utility must achieve to earn incentives or avoid penalties (e.g., SAIDI target of 90 minutes, customer satisfaction score of 85).',
    `pbr_variance` DECIMAL(18,2) COMMENT 'Calculated variance between the PBR actual value and the PBR target value (actual minus target). A positive variance may indicate over-performance (incentive-eligible) or under-performance depending on the metric direction convention.',
    `regulatory_jurisdiction` STRING COMMENT 'Identifies the jurisdictional authority governing this rate case: FERC for interstate transmission and wholesale rates, state PUC for retail distribution rates, or dual for proceedings with both jurisdictional components.. Valid values are `FERC|state_PUC|dual`',
    `requested_rate_base` DECIMAL(18,2) COMMENT 'Total rate base (net plant in service plus working capital allowances) requested by the utility in its filing, expressed in US dollars. Rate base is the foundation for calculating the allowed return on equity and overall revenue requirement.',
    `requested_revenue_requirement` DECIMAL(18,2) COMMENT 'Total annual revenue requirement requested by the utility in its initial rate case filing, expressed in US dollars. Represents the total cost of service the utility seeks to recover through rates, including O&M, depreciation, taxes, and return on rate base.',
    `requested_roe_pct` DECIMAL(18,2) COMMENT 'Return on Equity (ROE) percentage requested by the utility in its rate case filing. Represents the equity return component of the weighted average cost of capital used to calculate the allowed return on rate base.',
    `requested_wacc_pct` DECIMAL(18,2) COMMENT 'Weighted Average Cost of Capital (WACC) percentage requested by the utility, reflecting the blended cost of debt and equity in the proposed capital structure. Used to calculate the overall allowed return on rate base.',
    `settlement_date` DATE COMMENT 'Date on which the settlement agreement was executed by all parties. Populated only when settlement_indicator is True. Used to track the timeline of negotiated resolutions.',
    `settlement_indicator` BOOLEAN COMMENT 'Indicates whether the rate case was resolved through a negotiated settlement agreement between the utility and intervening parties rather than a fully litigated final order. True = settled; False = fully litigated.',
    `test_year_end_date` DATE COMMENT 'End date of the test year used to establish the revenue requirement and rate base. Together with test_year_start_date defines the 12-month test period for cost-of-service analysis.',
    `test_year_start_date` DATE COMMENT 'Start date of the test year (historical or future) used to establish the revenue requirement and rate base in this rate case. The test year is the 12-month period whose costs and revenues form the basis for rate-setting.',
    `test_year_type` STRING COMMENT 'Indicates whether the test year is based on historical recorded data, a future projected period, or a hybrid combining historical actuals with known and measurable adjustments.. Valid values are `historical|future|hybrid`',
    `true_up_amount` DECIMAL(18,2) COMMENT 'Dollar amount of the true-up adjustment calculated as the difference between interim rates collected and the final approved revenue requirement. A positive value indicates a refund owed to customers; a negative value indicates additional recovery owed to the utility.',
    `updated_timestamp` TIMESTAMP COMMENT 'Timestamp indicating when this rate case record was most recently modified. Used for change tracking, audit trail, and incremental data pipeline processing in the Databricks Silver Layer.',
    CONSTRAINT pk_rate_case PRIMARY KEY(`rate_case_id`)
) COMMENT 'Master record for each general rate case or rate proceeding filed with a state PUC or FERC. Tracks test year, filing date, requested revenue requirement, allowed ROE, rate base, capital structure, final approved rates, effective date, and interim rate/true-up adjustments. For proceedings with Performance-Based Ratemaking (PBR) components, captures PBR metric definitions (SAIDI, SAIFI, CAIDI, customer satisfaction, renewable integration %, EE savings, DR curtailment), approved target values, measurement periods, actual performance values, variance calculations, and earned incentive or assessed penalty amounts per measurement period. Links to parent docket. Serves as the SSOT for the complete rate case lifecycle from filing through final order, including all PBR performance tracking and incentive/penalty calculations. Critical for revenue requirement management, cost recovery authorization, and regulatory performance reporting.';

CREATE OR REPLACE TABLE `power_and_utilities`.`regulatory`.`tariff_schedule` (
    `tariff_schedule_id` BIGINT COMMENT 'Unique surrogate identifier for each tariff schedule record in the regulatory master. Serves as the primary key for the tariff_schedule data product on the Databricks Silver Layer.',
    `commission_order_id` BIGINT COMMENT 'Foreign key linking to regulatory.commission_order. Business justification: Tariff schedules are approved by commission orders. The tariff_schedule table currently has approval_order_number as STRING; this should be normalized to a FK relationship. Remove approval_order_numbe',
    `docket_id` BIGINT COMMENT 'Foreign key linking to regulatory.docket. Business justification: Tariff schedules are approved under regulatory dockets. The tariff_schedule table currently has docket_number as STRING; this should be normalized to a FK relationship. Remove docket_number STRING and',
    `financial_period_id` BIGINT COMMENT 'Foreign key linking to finance.financial_period. Business justification: Tariff effective dates must align with financial reporting periods for revenue recognition and regulatory accounting. Revenue accounting maps tariff schedules to financial periods for monthly revenue ',
    `rate_case_id` BIGINT COMMENT 'Reference to the rate case proceeding that established or last modified this tariff schedule. Links to the rate case master record for full regulatory proceeding context including testimony, prudency reviews, and cost-of-service studies.',
    `superseded_by_tariff_tariff_schedule_id` BIGINT COMMENT 'Self-referencing identifier pointing to the tariff_schedule record that replaced this schedule. Enables navigation of the tariff version chain for historical rate reconstruction and regulatory audit. Null if this schedule has not been superseded.',
    `applicable_season` STRING COMMENT 'The seasonal applicability of this tariff schedule or its rate components. Many utility tariffs have differentiated summer and winter rates reflecting seasonal demand patterns and fuel costs. All_year indicates no seasonal differentiation.. Valid values are `summer|winter|all_year|shoulder`',
    `approval_date` DATE COMMENT 'The date on which the regulatory authority issued the order approving this tariff schedule. Null for schedules that are pending approval or were withdrawn prior to approval.',
    `commodity_type` STRING COMMENT 'The energy commodity covered by this tariff schedule. Distinguishes electric service tariffs from natural gas distribution tariffs, or combined service offerings where applicable.. Valid values are `electric|gas|combined`',
    `created_timestamp` TIMESTAMP COMMENT 'The timestamp when this tariff schedule record was first created in the regulatory data product. Provides the audit trail for record origination in the Silver Layer lakehouse.',
    `currency_code` STRING COMMENT 'ISO 4217 three-letter currency code for all monetary rate components in this tariff schedule (e.g., USD). Ensures unambiguous currency context for rate values, particularly relevant for utilities operating across jurisdictions.. Valid values are `^[A-Z]{3}$`',
    `customer_charge` DECIMAL(18,2) COMMENT 'The fixed monthly customer charge (in dollars) applicable to all customers on this tariff schedule regardless of consumption or demand. Recovers fixed costs of metering, billing, and service connection. Also referred to as the basic service charge or meter charge.',
    `demand_charge_rate` DECIMAL(18,2) COMMENT 'The approved demand charge rate expressed in dollars per kilowatt ($/kW) of measured peak demand. Applicable to commercial and industrial tariff schedules with demand metering. Null for residential schedules without demand billing.',
    `demand_threshold_kw` DECIMAL(18,2) COMMENT 'The minimum or maximum kilowatt (kW) demand threshold that determines eligibility for this tariff schedule. Customers above or below this threshold may be required or eligible to take service under a different schedule. Used in rate class assignment and billing validation.',
    `dr_program_applicable` BOOLEAN COMMENT 'Indicates whether this tariff schedule includes or is associated with a Demand Response (DR) or Demand-Side Management (DSM) program provision. True if customers on this schedule are eligible for or subject to DR curtailment events and associated incentives or penalties.',
    `effective_date` DATE COMMENT 'The date on which this tariff schedule becomes legally effective and applicable to customers, as approved by the regulatory authority. This is the binding start date for rate application and billing purposes.',
    `energy_charge_rate` DECIMAL(18,2) COMMENT 'The approved volumetric energy charge rate expressed in dollars per kilowatt-hour ($/kWh) for electric tariffs or dollars per therm ($/therm) or dollars per MCF ($/MCF) for gas tariffs. Represents the core consumption-based component of the rate structure.',
    `energy_charge_unit` STRING COMMENT 'The unit of measure associated with the energy charge rate (e.g., kWh for residential electric, MWh for large commercial/industrial, therm or MCF for gas distribution). Ensures unambiguous interpretation of the energy_charge_rate value.. Valid values are `kWh|MWh|therm|MCF|kW`',
    `fac_rider_rate` DECIMAL(18,2) COMMENT 'The current approved Fuel Adjustment Clause (FAC) rider rate in dollars per kWh or therm, applied as a pass-through adjustment to recover actual fuel and purchased power costs above or below the base rate. Updated periodically per regulatory approval.',
    `filing_date` DATE COMMENT 'The date on which this tariff schedule was formally filed with the regulatory authority. Establishes the official filing record for docket tracking and regulatory compliance timelines.',
    `filing_state_code` STRING COMMENT 'Two-letter U.S. state code (ISO 3166-2:US) identifying the state in which this tariff is filed. Used for multi-state utility jurisdictional reporting and rate case management. Null for FERC-jurisdictional interstate tariffs.. Valid values are `^[A-Z]{2}$`',
    `interruptible_service` BOOLEAN COMMENT 'Indicates whether this tariff schedule provides interruptible service, where the utility retains the right to curtail or interrupt supply during system emergencies or peak demand events in exchange for a discounted rate. Common in large commercial and industrial gas and electric tariffs.',
    `jurisdiction` STRING COMMENT 'The regulatory jurisdiction under which this tariff schedule is filed and approved (e.g., FERC, CA PUC, TX PUC, NY PSC). Identifies the governing authority responsible for tariff approval and oversight.',
    `last_updated_timestamp` TIMESTAMP COMMENT 'The timestamp when this tariff schedule record was most recently modified in the regulatory data product. Supports change tracking, data lineage, and incremental ETL processing in the Databricks Silver Layer.',
    `minimum_bill_amount` DECIMAL(18,2) COMMENT 'The minimum monthly bill amount (in dollars) guaranteed under this tariff schedule, regardless of actual consumption. Ensures recovery of fixed costs for customers with very low usage. Null if no minimum bill provision applies.',
    `nem_export_rate` DECIMAL(18,2) COMMENT 'The approved credit rate in dollars per kWh applied to excess energy exported to the grid by customers with Distributed Energy Resources (DER) under Net Energy Metering (NEM) tariff schedules. Null for non-NEM schedules.',
    `pbr_applicable` BOOLEAN COMMENT 'Indicates whether this tariff schedule is subject to Performance-Based Ratemaking (PBR) mechanisms, where utility revenue or earnings are tied to performance metrics such as reliability (SAIDI/SAIFI), customer satisfaction, or clean energy targets. True if PBR provisions apply.',
    `rate_design_type` STRING COMMENT 'The rate design methodology applied in this tariff schedule. Distinguishes flat rates, tiered/inclining block rates, Time-of-Use (TOU), Critical Peak Pricing (CPP), Real-Time Pricing (RTP), and declining block structures. Drives billing calculation logic in Oracle CC&B or SAP IS-U. [ENUM-REF-CANDIDATE: flat|tiered|tou|cpp|rtp|inclining_block|declining_block — promote to reference product]',
    `schedule_description` STRING COMMENT 'Full narrative description of the tariff schedule as it appears in the approved tariff filing, including applicability conditions, service limitations, and special provisions. Provides the complete regulatory text context for compliance and customer communication purposes.',
    `schedule_name` STRING COMMENT 'Descriptive name of the tariff schedule as it appears in the approved tariff book (e.g., Residential Service, General Service Time-of-Use, Net Energy Metering, Open Access Transmission Tariff). Used for display and reporting purposes.',
    `schedule_status` STRING COMMENT 'Current lifecycle status of the tariff schedule in the regulatory approval and operational workflow. Pending indicates filed but not yet approved; Approved indicates regulatory approval received; Effective indicates currently in force; Superseded indicates replaced by a newer schedule; Withdrawn indicates filing withdrawn; Suspended indicates temporarily suspended by regulatory order.. Valid values are `pending|approved|effective|superseded|withdrawn|suspended`',
    `schedule_type` STRING COMMENT 'Classification of the tariff schedule by service and rate design category. Distinguishes electric residential, commercial Time-of-Use (TOU), Critical Peak Pricing (CPP), gas distribution, Open Access Transmission Tariff (OATT), Net Energy Metering (NEM), and demand response schedules. [ENUM-REF-CANDIDATE: electric_residential|electric_commercial|electric_tou|electric_cpp|gas_distribution|oatt|nem|demand_response — promote to reference product]',
    `service_class` STRING COMMENT 'The customer service class to which this tariff schedule applies. Segments the tariff applicability by customer category (e.g., residential, commercial, industrial, agricultural, street lighting, transmission). Aligns with PUC-approved rate class definitions.. Valid values are `residential|commercial|industrial|agricultural|lighting|transmission`',
    `special_conditions` STRING COMMENT 'Narrative description of any special conditions, eligibility restrictions, or limitations associated with this tariff schedule (e.g., minimum contract demand, geographic restrictions, equipment requirements, enrollment caps for NEM or DR programs).',
    `superseded_date` DATE COMMENT 'The date on which this tariff schedule was superseded by a newer approved schedule or withdrawn from effect. Null if the schedule is currently effective. Used to maintain the full historical record of approved tariff structures for regulatory audit and retroactive billing adjustments.',
    `tariff_book_section` STRING COMMENT 'The section or part of the utilitys tariff book in which this schedule is filed (e.g., Part A - Electric Service, Part B - Gas Service, Part C - Transmission). Supports navigation of the regulatory tariff document structure.',
    `tariff_number` STRING COMMENT 'The official tariff or rate schedule number as assigned by the regulatory authority (e.g., PUC or FERC). This is the externally-known identifier referenced in regulatory filings, dockets, and customer bills (e.g., Schedule E-1, Rate Schedule 10, OATT Schedule 1).',
    `tariff_sheet_number` STRING COMMENT 'The specific tariff sheet or leaf number within the utilitys tariff book as filed with the regulatory authority. Tariff books are organized by numbered sheets; this field identifies the precise sheet(s) containing this schedules terms and conditions.',
    `territory_code` STRING COMMENT 'Code identifying the utilitys service territory or operating division to which this tariff schedule applies. Relevant for multi-territory utilities with distinct rate zones or operating companies filing separate tariffs with different PUCs.',
    `tou_offpeak_rate` DECIMAL(18,2) COMMENT 'The approved off-peak energy charge rate in dollars per kWh for Time-of-Use (TOU) tariff schedules. Applied during hours outside the defined peak period. Null for non-TOU schedules.',
    `tou_peak_end_time` TIMESTAMP COMMENT 'The end time of the on-peak pricing period for Time-of-Use (TOU) tariff schedules, expressed in HH:MM 24-hour format. Null for non-TOU tariff schedules. Paired with tou_peak_start_time to define the peak billing window.',
    `tou_peak_rate` DECIMAL(18,2) COMMENT 'The approved on-peak energy charge rate in dollars per kWh for Time-of-Use (TOU) tariff schedules. Applied during the defined peak period hours. Null for non-TOU schedules.',
    `tou_peak_start_time` TIMESTAMP COMMENT 'The start time of the on-peak pricing period for Time-of-Use (TOU) tariff schedules, expressed in HH:MM 24-hour format. Null for non-TOU tariff schedules. Used in billing systems to apply differentiated energy charges by time of day.',
    `version_number` STRING COMMENT 'Sequential version number of this tariff schedule, incremented each time the schedule is revised and re-filed. Version 1 represents the original approved schedule. Supports version chain tracking alongside the superseded_by_tariff_id self-reference.',
    `voltage_level` STRING COMMENT 'The voltage level at which service is delivered under this tariff schedule. Determines applicable line loss factors and delivery charges. Secondary voltage applies to most residential and small commercial customers; primary and transmission voltage applies to large industrial customers taking service at higher voltages.. Valid values are `secondary|primary|transmission|subtransmission`',
    CONSTRAINT pk_tariff_schedule PRIMARY KEY(`tariff_schedule_id`)
) COMMENT 'Master record for each approved tariff schedule, rate schedule, or tariff sheet on file with a regulatory authority. Captures tariff number, schedule type (electric residential, commercial TOU, CPP, gas distribution, OATT, NEM), effective date, superseded date, jurisdiction, approval order reference, and rate components (energy charge, demand charge, customer charge, FAC rider). Serves as the regulatory SSOT for approved tariff structures distinct from the billing domains operational rate application.';

CREATE OR REPLACE TABLE `power_and_utilities`.`regulatory`.`filing` (
    `filing_id` BIGINT COMMENT 'Unique surrogate identifier for each regulatory filing record in the lakehouse silver layer. Primary key for the filing data product.',
    `commission_order_id` BIGINT COMMENT 'Foreign key linking to regulatory.commission_order. Business justification: Commission orders often require compliance filings (e.g., Utility shall file updated depreciation study within 90 days). This FK links the responsive filing to the order that mandated it. N:1 cardin',
    `compliance_obligation_id` BIGINT COMMENT 'Foreign key linking to regulatory.compliance_obligation. Business justification: Many filings are submitted to fulfill ongoing compliance obligations (quarterly NERC reports, annual RPS compliance filings, GHG emissions reports). Linking filing to compliance_obligation tracks whic',
    `cpcn_application_id` BIGINT COMMENT 'Foreign key linking to regulatory.cpcn_application. Business justification: Filings in CPCN dockets should reference the cpcn_application record. While filing already has docket_id, adding cpcn_application_id provides direct linkage when the filing is part of a CPCN proceedin',
    `docket_id` BIGINT COMMENT 'Reference to the parent regulatory docket or proceeding under which this filing is submitted. Links the filing to its governing case or proceeding at the regulatory body.',
    `irp_submission_id` BIGINT COMMENT 'Foreign key linking to regulatory.irp_submission. Business justification: IRP submissions generate multiple filings: initial plan filing, responses to data requests, updated forecasts, public comment responses. Each filing document should reference its parent IRP submission',
    `rate_case_id` BIGINT COMMENT 'Foreign key linking to regulatory.rate_case. Business justification: Filings in rate case dockets should reference the rate_case record. While filing already has docket_id, adding rate_case_id provides direct linkage when the filing is part of a rate case proceeding. T',
    `superseded_by_filing_id` BIGINT COMMENT 'Reference to the filing_id of the subsequent filing that replaces this one when filing_status is superseded. Enables traceability of the amendment chain and identification of the current authoritative version of a filing.',
    `tariff_schedule_id` BIGINT COMMENT 'Foreign key linking to regulatory.tariff_schedule. Business justification: Filings that propose tariff changes should reference the tariff_schedule being modified. The filing table currently has tariff_schedule_number as STRING; this should be normalized to a FK relationship',
    `accepted_date` DATE COMMENT 'Date on which the regulatory body formally accepted and docketed the filing. Distinct from the filing date; acceptance triggers statutory response deadlines and effective date calculations for tariff filings.',
    `confidentiality_designation` STRING COMMENT 'Data classification level assigned to the filing document, governing access controls and public disclosure obligations. public filings are available on the regulatory bodys public docket; confidential filings are subject to protective order or CEII (Critical Energy Infrastructure Information) designation; restricted filings contain highly sensitive operational or security data.. Valid values are `public|internal|confidential|restricted`',
    `cost_recovery_mechanism` STRING COMMENT 'Identifies the regulatory cost recovery mechanism associated with this filing. fac = Fuel Adjustment Clause; afudc = Allowance for Funds Used During Construction; ciac = Contribution in Aid of Construction; wip = Work in Progress; rider = regulatory rider; surcharge = customer surcharge; base_rate = general rate case base rate recovery. [ENUM-REF-CANDIDATE: fac|afudc|ciac|wip|rider|surcharge|base_rate — 7 candidates stripped; promote to reference product]',
    `created_timestamp` TIMESTAMP COMMENT 'Timestamp when this filing record was first created in the regulatory data management system. Supports audit trail requirements and record lineage tracking in the lakehouse silver layer.',
    `cross_examination_date` DATE COMMENT 'Scheduled date on which the witness is available for cross-examination by parties to the proceeding. Populated for testimony filings as part of the hearing schedule management. Null for non-testimony filings.',
    `document_title` STRING COMMENT 'Official title of the filed document as it appears on the submission (e.g., Application for Certificate of Public Convenience and Necessity, Direct Testimony of Jane Doe on Revenue Requirement, Annual FERC Form 1 Report).',
    `document_url` STRING COMMENT 'Uniform Resource Locator (URL) or document management system path pointing to the filed document in the utilitys internal document repository or the regulatory bodys public docket system. Enables direct retrieval of the source document.',
    `effective_date` DATE COMMENT 'Date on which the rates, tariff provisions, or regulatory requirements established by the filing become operative. For tariff filings, this is the date new rates take effect. For compliance filings, this is the date the compliance obligation is satisfied.',
    `epa_regulation_citation` STRING COMMENT 'Citation to the specific U.S. Environmental Protection Agency (EPA) regulation or rule (e.g., 40 CFR Part 75 for acid rain emissions, Clean Air Act Section 111(d)) under which this filing is submitted. Populated for EPA emissions reports and environmental compliance filings.',
    `exhibit_list` STRING COMMENT 'Comma-separated or delimited list of exhibit identifiers (e.g., Exhibit A, Exhibit 1, Schedule 1) attached to or sponsored by this filing. Captures the evidentiary exhibit inventory associated with the submission for record completeness.',
    `filer_name` STRING COMMENT 'Legal name of the entity or individual submitting the filing to the regulatory body. Typically the utilitys legal entity name, but may be an attorney, consultant, or authorized representative filing on behalf of the utility.',
    `filer_role` STRING COMMENT 'Designates the capacity in which the filer is participating in the proceeding. Distinguishes utility filings from intervenor, PUC staff, or independent expert submissions within the same docket.. Valid values are `utility|intervenor|puc_staff|independent_expert|attorney`',
    `filing_date` DATE COMMENT 'The official date on which the filing was submitted to the regulatory body. This is the principal business event date used for compliance deadline tracking, tariff effective date calculations, and regulatory calendar management.',
    `filing_description` STRING COMMENT 'Free-text narrative description of the filings purpose, scope, and key provisions. Provides regulatory affairs staff and analysts with a plain-language summary of what the filing accomplishes and its significance to the utilitys regulatory program.',
    `filing_number` STRING COMMENT 'Externally assigned document reference number issued by the regulatory body upon acceptance of the filing (e.g., FERC accession number, PUC filing number). Serves as the official public identifier for the submission.',
    `filing_status` STRING COMMENT 'Current lifecycle state of the filing within the regulatory submission workflow. draft indicates preparation in progress; submitted indicates transmission to the regulatory body; accepted indicates formal docketing; rejected indicates non-acceptance requiring resubmission; superseded indicates replaced by a subsequent filing; withdrawn indicates voluntarily recalled by the filer.. Valid values are `draft|submitted|accepted|rejected|superseded|withdrawn`',
    `filing_type` STRING COMMENT 'Classification of the regulatory submission by its formal document category. Distinguishes the nature and purpose of the filing within the regulatory proceeding. [ENUM-REF-CANDIDATE: initial_application|testimony|exhibit|compliance_filing|annual_report|nerc_reliability_standard|epa_emissions_report|tariff_filing|rate_case|cpcn_application|irp_submission|errata — promote to reference product]',
    `ghg_reporting_period_end` DATE COMMENT 'End date of the greenhouse gas (GHG) emissions reporting period covered by this filing. Together with ghg_reporting_period_start, defines the compliance reporting window for EPA GHG submissions.',
    `ghg_reporting_period_start` DATE COMMENT 'Start date of the greenhouse gas (GHG) emissions reporting period covered by this filing. Applicable to EPA GHG emissions reports and environmental compliance submissions under the Clean Air Act.',
    `internal_reference_number` STRING COMMENT 'Utility-assigned internal tracking number for the filing, used to cross-reference the submission in internal document management and regulatory affairs systems prior to or independent of the regulatory bodys assigned number.',
    `is_testimony` BOOLEAN COMMENT 'Flag indicating whether this filing is a formal witness testimony submission (direct, rebuttal, surrebuttal, or errata testimony) as opposed to a non-testimony filing such as an application, exhibit, or compliance report. Drives testimony-specific attribute population.',
    `jurisdiction_state` STRING COMMENT 'Two-letter U.S. state abbreviation identifying the state jurisdiction applicable to this filing. Populated for state PUC filings; may be null for federal filings (FERC, NERC, EPA) that are not state-specific.. Valid values are `^[A-Z]{2}$`',
    `nerc_standard_number` STRING COMMENT 'Identifier of the North American Electric Reliability Corporation (NERC) reliability standard (e.g., CIP-002, FAC-001, TPL-001) to which this filing pertains. Populated for NERC compliance filings and reliability standard submissions.',
    `page_count` STRING COMMENT 'Total number of pages in the filed document. Used for document management, completeness verification, and regulatory record-keeping.',
    `pbr_mechanism_flag` BOOLEAN COMMENT 'Indicates whether this filing involves or establishes a performance-based ratemaking (PBR) mechanism, linking utility revenue or earnings to performance metrics such as reliability (SAIDI/SAIFI), customer satisfaction, or clean energy targets.',
    `prudency_review_flag` BOOLEAN COMMENT 'Indicates whether this filing is subject to a regulatory prudency review of capital expenditures or operational costs. Prudency reviews assess whether utility expenditures were made in a reasonable and prudent manner for cost recovery purposes.',
    `rate_case_year` STRING COMMENT 'The test year or rate case year associated with this filing, representing the calendar or fiscal year for which rates or revenue requirements are being established. Applicable to rate case filings, IRP submissions, and annual reports.',
    `regulatory_body` STRING COMMENT 'The governmental or quasi-governmental authority to which the filing is submitted. Identifies the jurisdictional regulator: Federal Energy Regulatory Commission (FERC), North American Electric Reliability Corporation (NERC), U.S. Environmental Protection Agency (EPA), State Public Utility Commission (PUC), U.S. Department of Energy (DOE), Pipeline and Hazardous Materials Safety Administration (PHMSA), or Occupational Safety and Health Administration (OSHA). [ENUM-REF-CANDIDATE: FERC|NERC|EPA|PUC|DOE|PHMSA|OSHA — 7 candidates stripped; promote to reference product]',
    `requested_rate_increase_pct` DECIMAL(18,2) COMMENT 'Percentage rate increase requested in this filing relative to currently approved rates. Applicable to rate case and tariff amendment filings. Used for regulatory impact analysis and public reporting.',
    `response_due_date` DATE COMMENT 'Deadline by which the utility or other parties must respond to a regulatory bodys data request, deficiency letter, or order related to this filing. Critical for compliance deadline tracking and regulatory calendar management.',
    `revenue_requirement_amount` DECIMAL(18,2) COMMENT 'Total revenue requirement amount (in USD) proposed or established by this filing. Applicable to rate case applications and revenue requirement testimony filings. Represents the total annual revenue the utility is authorized or requesting to collect from customers.',
    `submission_method` STRING COMMENT 'Method by which the filing was transmitted to the regulatory body. Most modern filings are submitted electronically via FERCs eFiling system or state PUC e-filing portals; legacy or emergency filings may be submitted by paper, hand delivery, or email.. Valid values are `electronic|paper|hand_delivery|email`',
    `testimony_subject` STRING COMMENT 'Describes the primary regulatory topic addressed by the testimony. Common subjects include revenue requirement, rate design, capital structure, depreciation, demand forecast, cost of capital, performance-based ratemaking (PBR), and demand-side management (DSM). Null for non-testimony filings. [ENUM-REF-CANDIDATE: revenue_requirement|rate_design|capital_structure|depreciation|demand_forecast|cost_of_capital|pbr|dsm|ghg_compliance|fuel_adjustment — promote to reference product]',
    `testimony_type` STRING COMMENT 'For testimony filings, classifies the stage of the evidentiary record at which the testimony is submitted. direct is the initial witness statement; rebuttal responds to opposing direct testimony; surrebuttal responds to rebuttal testimony; errata corrects errors in previously filed testimony. Null for non-testimony filings.. Valid values are `direct|rebuttal|surrebuttal|errata`',
    `updated_timestamp` TIMESTAMP COMMENT 'Timestamp of the most recent update to this filing record in the regulatory data management system. Used to detect changes, support incremental ETL processing, and maintain audit trail integrity.',
    `witness_affiliation` STRING COMMENT 'Organizational affiliation of the testifying witness, indicating which party in the proceeding the witness represents. Distinguishes utility witnesses from intervenor, PUC staff, and independent expert witnesses for evidentiary record management.. Valid values are `utility|intervenor|puc_staff|independent_expert`',
    `witness_name` STRING COMMENT 'Full name of the expert witness sponsoring the testimony filing. Populated only for testimony-type filings. Used to track the evidentiary record and cross-examination schedule in rate cases and contested proceedings.',
    CONSTRAINT pk_filing PRIMARY KEY(`filing_id`)
) COMMENT 'Transactional record of each formal document or submission filed with a regulatory body (PUC, FERC, NERC, EPA, DOE, PHMSA). Captures filing type (initial application, testimony, exhibit, compliance filing, annual report, NERC reliability standard filing, EPA emissions report), filing date, filer name, filing status (draft, submitted, accepted, rejected, superseded), regulatory body, associated docket, document reference number, and confidentiality designation. For testimony filings (direct, rebuttal, surrebuttal, errata), additionally captures witness name, witness affiliation (utility, intervenor, PUC staff, independent expert), testimony subject matter (revenue requirement, rate design, capital structure, depreciation, demand forecast), exhibit list, and cross-examination schedule. Links to parent docket. Serves as the SSOT for all documents submitted to regulatory authorities, including the complete evidentiary testimony record for rate cases and contested proceedings.';

CREATE OR REPLACE TABLE `power_and_utilities`.`regulatory`.`cpcn_application` (
    `cpcn_application_id` BIGINT COMMENT 'Unique surrogate identifier for each CPCN application record in the regulatory data product. Primary key for the cpcn_application table in the Databricks Silver Layer.',
    `commission_order_id` BIGINT COMMENT 'Foreign key linking to regulatory.commission_order. Business justification: CPCN applications are approved or denied by commission orders. The cpcn_application table should reference the commission_order that issued the final decision. This is a standard parent-child relation',
    `capex_project_id` BIGINT COMMENT 'Reference to the associated capital project record in the Enterprise Asset Management (EAM) or ERP system (e.g., SAP S/4HANA or Oracle WAM/Maximo). Links the regulatory authorization to the capital expenditure (CAPEX) project for financial tracking including AFUDC and WIP accounting.',
    `docket_id` BIGINT COMMENT 'Foreign key linking to regulatory.docket. Business justification: CPCN applications are filed under regulatory dockets. The cpcn_application table currently has docket_number as STRING; this should be normalized to a FK relationship. Remove docket_number STRING and ',
    `interconnection_request_id` BIGINT COMMENT 'External identifier assigned by the RTO/ISO or transmission provider for the associated generator or transmission interconnection request. Links the CPCN regulatory authorization to the parallel interconnection study process.',
    `irp_submission_id` BIGINT COMMENT 'Foreign key linking to regulatory.irp_submission. Business justification: CPCN applications should demonstrate alignment with the utilitys Integrated Resource Plan. The cpcn_application table has irp_alignment_flag BOOLEAN; when true, there should be a FK to the specific i',
    `party_id` BIGINT COMMENT 'Reference to the legal entity (utility operating company or subsidiary) filing the CPCN application. Supports multi-jurisdictional utilities with multiple operating companies filing under different PUC jurisdictions.',
    `master_id` BIGINT COMMENT 'Foreign key linking to asset.asset_master. Business justification: CPCN applications approve construction of specific major assets (transmission lines, substations, generation units). Links regulatory approval to the primary asset constructed. Essential for tracking ',
    `acceptance_date` DATE COMMENT 'Date on which the regulatory agency formally accepted the CPCN application as complete and docketed it for review. Distinct from filing_date; acceptance triggers the official statutory review period.',
    `application_status` STRING COMMENT 'Current lifecycle status of the CPCN application within the regulatory proceeding. Tracks progression from internal drafting through PUC/FERC review to final disposition. [ENUM-REF-CANDIDATE: draft|filed|pending_review|evidentiary_hearing|approved|conditionally_approved|denied|withdrawn|suspended — promote to reference product]',
    `applied_capacity_mw` DECIMAL(18,2) COMMENT 'Nameplate or rated capacity in megawatts (MW) for generation or substation projects as stated in the CPCN application. Null for linear infrastructure (transmission lines, pipelines) where line_length_miles is the primary measurement. Used for IRP capacity planning and PUC capacity need determinations.',
    `certificate_expiry_date` DATE COMMENT 'Date on which the issued CPCN certificate expires if construction has not commenced or the project has not been placed in service. Utilities must seek an extension or re-file if this date passes without project completion.',
    `certificate_issuance_date` DATE COMMENT 'Date on which the CPCN certificate was formally issued to the utility following approval. This date authorizes commencement of construction or operation and is the key milestone for capital project scheduling and AFUDC accrual start.',
    `conditions_of_approval` STRING COMMENT 'Narrative description of any conditions, mitigation measures, or compliance obligations imposed by the PUC or FERC as part of a conditional approval. Null for unconditional approvals or pending applications. Populated from the regulatory order text.',
    `construction_start_date` DATE COMMENT 'Earliest date on which construction may commence per the CPCN certificate conditions. May differ from the certificate_issuance_date if the certificate imposes pre-construction conditions (e.g., environmental mitigation plan approval).',
    `cost_recovery_mechanism` STRING COMMENT 'Regulatory mechanism through which the utility intends to recover the costs of the project from customers. Rate_base: included in general rate case; rider/tracker: separate cost recovery surcharge; CIAC: customer-funded contribution; PPA: recovered through purchased power costs.. Valid values are `rate_base|rider|tracker|CIAC|PPA|other`',
    `created_timestamp` TIMESTAMP COMMENT 'Timestamp when the CPCN application record was first created in the regulatory data system. Audit field supporting data lineage and record provenance in the Databricks Silver Layer.',
    `decision_date` DATE COMMENT 'Date on which the PUC or FERC issued its final order approving, conditionally approving, or denying the CPCN application. Null until a final decision is rendered.',
    `denial_reason` STRING COMMENT 'Narrative description of the regulatory agencys stated basis for denying the CPCN application. Null for approved or pending applications. Used for regulatory strategy analysis and re-filing preparation.',
    `environmental_review_status` STRING COMMENT 'Current status of the environmental review process associated with the CPCN application. Tracks progression from initiation through draft and final publication to completion. A prerequisite for certificate issuance in most jurisdictions.. Valid values are `not_required|initiated|draft_published|final_published|complete`',
    `environmental_review_type` STRING COMMENT 'Type of environmental review required or completed for the project. EIS (Environmental Impact Statement) and EA (Environmental Assessment) are federal NEPA categories; CEQA applies in California; state_environmental_review covers other state-level equivalents. Drives permitting timelines and conditions of approval.. Valid values are `EIS|EA|CEQA|NEPA_categorical_exclusion|state_environmental_review|none`',
    `estimated_capex_usd` DECIMAL(18,2) COMMENT 'Total estimated capital expenditure (CAPEX) in US dollars as stated in the CPCN application. Used for rate base determination, AFUDC calculation, and prudency review. Confidential as it contains commercially sensitive cost estimates submitted in regulatory proceedings.',
    `evidentiary_hearing_date` DATE COMMENT 'Scheduled or actual date of the evidentiary hearing before the PUC or FERC administrative law judge. Null if the application is processed on the written record without a hearing.',
    `ferc_section_203_flag` BOOLEAN COMMENT 'Indicates whether the project also requires separate authorization under Federal Power Act Section 203 (disposition of jurisdictional facilities). True if the project involves a merger, acquisition, or disposition of FERC-jurisdictional assets in addition to the state CPCN.',
    `filing_date` DATE COMMENT 'The date on which the CPCN application was formally filed with the PUC or FERC. This is the principal business event timestamp that initiates the regulatory review clock and establishes statutory deadlines for agency action.',
    `fuel_technology_type` STRING COMMENT 'Fuel source or generation technology type for generation projects (e.g., natural gas combined cycle, solar photovoltaic, wind, nuclear, hydro). For transmission and distribution projects, describes the primary technology (e.g., overhead line, underground cable, gas pipeline). Informs environmental review, RPS compliance, and IRP alignment. [ENUM-REF-CANDIDATE: natural_gas_cc|natural_gas_ct|nuclear|solar_pv|wind|hydro|battery_storage|overhead_transmission|underground_cable|gas_pipeline — promote to reference product]',
    `ghg_emissions_impact_tons` DECIMAL(18,2) COMMENT 'Estimated annual greenhouse gas (GHG) emissions impact of the project in metric tons of CO2 equivalent (CO2e) as reported in the environmental review. Positive values indicate net emissions increase; negative values indicate net reduction (e.g., for renewable projects displacing fossil generation). Required for EPA and state GHG compliance reporting.',
    `in_service_target_date` DATE COMMENT 'Projected date by which the infrastructure is expected to be placed in commercial service as stated in the CPCN application. Used for IRP resource adequacy planning, RTO/ISO interconnection scheduling, and capital project milestone tracking.',
    `infrastructure_type` STRING COMMENT 'Classification of the infrastructure category for which the CPCN is being sought. Determines the applicable regulatory framework, filing requirements, and reviewing authority (PUC vs. FERC). [ENUM-REF-CANDIDATE: generation|transmission|distribution|gas_pipeline|substation|storage|interconnection — promote to reference product]. Valid values are `generation|transmission|distribution|gas_pipeline|substation`',
    `intervenor_count` STRING COMMENT 'Number of parties that have formally intervened in the CPCN proceeding as of the most recent update. High intervenor counts indicate contested proceedings and are a leading indicator of hearing complexity and timeline risk.',
    `irp_alignment_flag` BOOLEAN COMMENT 'Indicates whether the proposed project is included in the utilitys most recently approved Integrated Resource Plan (IRP). True if the project is IRP-identified; False if it is an out-of-cycle or supplemental filing. IRP alignment is a key factor in PUC prudency review.',
    `jurisdiction_code` STRING COMMENT 'Identifies the primary regulatory jurisdiction governing this CPCN application. FERC for interstate transmission and wholesale facilities; STATE_PUC for intrastate distribution and retail facilities; DUAL for projects requiring both federal and state authorization.. Valid values are `FERC|STATE_PUC|DUAL`',
    `lead_project_manager` STRING COMMENT 'Name of the capital project manager responsible for the infrastructure project associated with this CPCN application. Links regulatory authorization tracking to project delivery accountability.',
    `lead_regulatory_counsel` STRING COMMENT 'Name of the internal or external legal counsel designated as lead attorney for the CPCN proceeding. Used for regulatory case management, document routing, and accountability tracking.',
    `line_length_miles` DECIMAL(18,2) COMMENT 'Total route length in miles for transmission lines, distribution circuits, or gas pipeline projects as stated in the CPCN application. Null for point-source generation and substation projects where applied_capacity_mw is the primary measurement.',
    `nerc_bes_flag` BOOLEAN COMMENT 'Indicates whether the proposed facility meets the NERC definition of a Bulk Electric System (BES) element, triggering mandatory NERC reliability standards compliance obligations. True for transmission facilities at or above 100 kV and generation above applicable thresholds.',
    `ppa_associated_flag` BOOLEAN COMMENT 'Indicates whether the CPCN application is associated with a Power Purchase Agreement (PPA) rather than a utility-owned build. True if the project involves a third-party developer under a PPA; False for utility self-build projects. Affects rate treatment and cost recovery mechanism.',
    `project_name` STRING COMMENT 'Human-readable name of the generation, transmission, or distribution infrastructure project for which the CPCN is being sought. Used in regulatory filings, public notices, and internal capital project tracking.',
    `rate_base_eligible_flag` BOOLEAN COMMENT 'Indicates whether the project costs are expected to be included in the utilitys regulated rate base upon completion, enabling cost recovery through customer rates. False for projects funded via CIAC (Contribution in Aid of Construction) or other non-rate-base mechanisms.',
    `rec_eligible_flag` BOOLEAN COMMENT 'Indicates whether the generation project is eligible to generate Renewable Energy Certificates (RECs) under the applicable state Renewable Portfolio Standard (RPS). True for qualifying renewable generation technologies; False for fossil fuel and nuclear projects.',
    `rto_iso_region` STRING COMMENT 'The RTO or ISO region in which the project is located (e.g., CAISO, MISO, PJM, ERCOT, SPP, NYISO, ISO-NE). Determines interconnection study requirements, transmission planning obligations, and applicable OATT provisions.',
    `service_territory` STRING COMMENT 'Description of the geographic service territory or region where the proposed infrastructure will be located or will serve. May reference county, utility planning area, load zone, or RTO/ISO region. Used for jurisdictional determination and public notice requirements.',
    `state_code` STRING COMMENT 'Two-letter US state abbreviation (e.g., CA, TX, NY) identifying the primary state jurisdiction where the CPCN application is filed. Determines the applicable PUC and state regulatory requirements.. Valid values are `^[A-Z]{2}$`',
    `statutory_deadline_date` DATE COMMENT 'The date by which the regulatory agency is statutorily required to issue a final decision on the CPCN application. Calculated from the acceptance_date based on applicable state or federal procedural rules. Used for regulatory compliance monitoring and project schedule management.',
    `updated_timestamp` TIMESTAMP COMMENT 'Timestamp when the CPCN application record was most recently modified in the regulatory data system. Used for incremental ETL processing, change detection, and audit trail maintenance in the Databricks Silver Layer.',
    `voltage_kv` DECIMAL(18,2) COMMENT 'Nominal operating voltage in kilovolts (kV) for transmission or distribution infrastructure projects. Determines whether the project falls under FERC or state PUC jurisdiction (bulk electric system threshold) and applicable NERC reliability standards.',
    CONSTRAINT pk_cpcn_application PRIMARY KEY(`cpcn_application_id`)
) COMMENT 'Master record for each Certificate of Public Convenience and Necessity (CPCN) application filed for new generation, transmission, or distribution infrastructure. Tracks project name, applied capacity (MW or miles), fuel/technology type, service territory, filing date, environmental review status, PUC/FERC approval status, certificate issuance date, conditions of approval, and associated capital project reference. Essential for tracking regulatory authorization of major capital investments.';

CREATE OR REPLACE TABLE `power_and_utilities`.`regulatory`.`irp_submission` (
    `irp_submission_id` BIGINT COMMENT 'Unique surrogate identifier for each Integrated Resource Plan (IRP) submission record in the lakehouse Silver layer. Primary key for this entity.',
    `commission_order_id` BIGINT COMMENT 'Foreign key linking to regulatory.commission_order. Business justification: IRP submissions are acknowledged or approved by commission orders. The irp_submission table currently has puc_order_number as STRING; this should be normalized to a FK relationship. Remove puc_order_n',
    `docket_id` BIGINT COMMENT 'Foreign key linking to regulatory.docket. Business justification: IRP submissions are filed under regulatory dockets. The irp_submission table currently has docket_number as STRING; this should be normalized to a FK relationship. Remove docket_number STRING and repl',
    `rto_iso_id` BIGINT COMMENT 'FK to market.rto_iso',
    `alternative_scenarios_count` STRING COMMENT 'The number of alternative resource portfolio scenarios evaluated and documented in the IRP filing, beyond the preferred plan (e.g., high renewable, high gas, high EE scenarios).',
    `alternative_scenarios_description` STRING COMMENT 'Narrative summary of the alternative resource portfolio scenarios evaluated in the IRP, including key assumptions and distinguishing characteristics of each scenario.',
    `created_timestamp` TIMESTAMP COMMENT 'The timestamp when this IRP submission record was first created in the regulatory data system, capturing the audit trail for record origination.',
    `dr_capacity_mw` DECIMAL(18,2) COMMENT 'Total Demand Response (DR) capacity in Megawatts (MW) included in the preferred resource portfolio, representing load curtailment and peak shaving programs available to meet resource adequacy requirements.',
    `ee_savings_mw` DECIMAL(18,2) COMMENT 'Total Energy Efficiency (EE) program savings in Megawatts (MW) of peak demand reduction included in the preferred resource portfolio, representing avoided capacity from DSM programs.',
    `energy_type` STRING COMMENT 'Indicates whether the IRP covers electric resource planning, gas supply planning, or a combined electric and gas integrated plan, reflecting the utilitys service territory scope.. Valid values are `electric|gas|combined`',
    `filing_date` DATE COMMENT 'The date on which the IRP was formally submitted to the state PUC or applicable energy authority. Serves as the official commencement date of the regulatory proceeding.',
    `fossil_capacity_mw` DECIMAL(18,2) COMMENT 'Total installed or planned fossil fuel generation capacity (coal, natural gas CT/CC, oil) in Megawatts (MW) included in the preferred resource portfolio at the end of the planning horizon.',
    `ghg_emissions_target_tons` DECIMAL(18,2) COMMENT 'The GHG emissions reduction target in metric tons of CO2 equivalent (CO2e) for the utilitys generation portfolio at the end of the planning horizon, as required by state climate policy or PUC order.',
    `irp_approval_condition` STRING COMMENT 'Description of any conditions, modifications, or compliance requirements attached to the PUCs approval of the IRP, such as required supplemental filings, program modifications, or reporting obligations.',
    `irp_consultant_name` STRING COMMENT 'Name of the external consulting firm or advisor engaged to support development of the IRP, if applicable. Relevant for procurement transparency and regulatory disclosure.',
    `irp_document_reference` STRING COMMENT 'File path, document management system reference, or URL pointing to the official IRP filing document(s) stored in the utilitys document management system or the PUCs electronic filing system.',
    `irp_type` STRING COMMENT 'Classifies the nature of the IRP submission: full plan (complete new IRP cycle), update (periodic progress update to an existing IRP), or amendment (correction or modification to a previously filed IRP).. Valid values are `full|update|amendment`',
    `irp_version_number` STRING COMMENT 'Version identifier for the IRP document, used to distinguish successive drafts, amendments, or errata filings within the same plan cycle year (e.g., v1.0, v1.1, v2.0).',
    `is_rps_compliant` BOOLEAN COMMENT 'Indicates whether the preferred resource plan as filed demonstrates compliance with the applicable state Renewable Portfolio Standard (RPS) target for the planning horizon end year. True if compliant, False if a compliance gap exists.',
    `jurisdiction_code` STRING COMMENT 'Two-letter U.S. state abbreviation identifying the regulatory jurisdiction (state PUC) to which this IRP is filed (e.g., CA, TX, NY). Supports multi-state utility operations.. Valid values are `^[A-Z]{2}$`',
    `load_forecast_methodology` STRING COMMENT 'Description of the methodology used to develop the long-range load forecast underpinning the IRP, including econometric models, weather normalization approach, and EV/DER adoption assumptions.',
    `nerc_reliability_standard_ref` STRING COMMENT 'Reference to the applicable NERC reliability standard(s) (e.g., TPL-001-4, BAL-502) that inform the resource adequacy and planning reserve margin requirements addressed in this IRP.',
    `next_update_due_date` DATE COMMENT 'The date by which the utility is required to file the next IRP update or full plan revision, as mandated by the applicable PUC order or statute.',
    `nuclear_capacity_mw` DECIMAL(18,2) COMMENT 'Total installed or planned nuclear generation capacity in Megawatts (MW) included in the preferred resource portfolio at the end of the planning horizon.',
    `peak_demand_forecast_mw` DECIMAL(18,2) COMMENT 'Total forecasted system peak demand in Megawatts (MW) at the end of the planning horizon, representing the maximum load the utility must be capable of serving. Core resource adequacy metric.',
    `plan_cycle_year` STRING COMMENT 'The calendar year in which this IRP cycle is initiated, typically corresponding to the year of filing. Used to distinguish successive IRP cycles (e.g., 2022, 2025, 2028).',
    `planning_horizon_years` STRING COMMENT 'The number of years covered by the IRPs forward-looking resource adequacy analysis, typically 10 to 20 years. Defines the temporal scope of the resource portfolio projections.',
    `ppa_capacity_mw` DECIMAL(18,2) COMMENT 'Total generation capacity in Megawatts (MW) to be procured through Power Purchase Agreements (PPAs) as part of the preferred resource plan, as opposed to utility-owned generation.',
    `preferred_plan_description` STRING COMMENT 'Narrative description of the utilitys preferred resource plan, summarizing the selected portfolio of generation, storage, DR, and EE resources that best meets reliability, cost, and policy objectives over the planning horizon.',
    `public_comment_period_end_date` DATE COMMENT 'The date on which the public comment period for the IRP filing closes, as established by the PUC procedural schedule. After this date, no new public comments are accepted.',
    `puc_acknowledgment_date` DATE COMMENT 'The date on which the state PUC or energy authority formally acknowledged receipt and completeness of the IRP filing, initiating the official review period.',
    `puc_approval_date` DATE COMMENT 'The date on which the state PUC issued a final order approving, conditionally approving, or accepting the IRP. Null if the IRP has not yet received a final PUC disposition.',
    `regulatory_authority_name` STRING COMMENT 'Full name of the state PUC, energy office, or other regulatory authority to which the IRP is submitted (e.g., California Public Utilities Commission, New York Public Service Commission).',
    `renewable_capacity_mw` DECIMAL(18,2) COMMENT 'Total installed or planned renewable generation capacity (solar, wind, hydro, geothermal, biomass) in Megawatts (MW) in the preferred resource portfolio at the end of the planning horizon.',
    `reserve_margin_pct` DECIMAL(18,2) COMMENT 'The planning reserve margin percentage above forecasted peak demand required to ensure resource adequacy, expressed as a percentage (e.g., 15.0 for 15%). Typically set by the RTO/ISO or state PUC.',
    `rps_compliance_pct` DECIMAL(18,2) COMMENT 'The projected Renewable Portfolio Standard (RPS) compliance percentage achieved by the preferred resource plan at the end of the planning horizon, expressed as a percentage of total retail electricity sales from eligible renewable sources.',
    `rps_target_pct` DECIMAL(18,2) COMMENT 'The mandated RPS target percentage that the utility must achieve by the end of the planning horizon, as established by state statute or PUC order.',
    `storage_capacity_mw` DECIMAL(18,2) COMMENT 'Total installed or planned energy storage capacity in Megawatts (MW) included in the preferred resource portfolio, including battery storage and pumped hydro.',
    `submission_status` STRING COMMENT 'Current lifecycle status of the IRP submission within the regulatory proceeding. Tracks progression from internal drafting through PUC acknowledgment and final disposition. [ENUM-REF-CANDIDATE: draft|filed|acknowledged|under_review|approved|rejected|withdrawn — promote to reference product]',
    `total_capex_forecast_usd` DECIMAL(18,2) COMMENT 'Total projected Capital Expenditure (CAPEX) in U.S. dollars required to implement the preferred resource plan over the planning horizon, as presented in the IRP filing.',
    `total_opex_forecast_usd` DECIMAL(18,2) COMMENT 'Total projected Operating Expenditure (OPEX) in U.S. dollars associated with the preferred resource plan over the planning horizon, as presented in the IRP filing.',
    `updated_timestamp` TIMESTAMP COMMENT 'The timestamp when this IRP submission record was most recently modified, supporting audit trail and change tracking requirements.',
    `utility_code` BIGINT COMMENT 'Reference to the utility legal entity or operating company filing the IRP. Supports multi-utility or holding company structures where multiple operating companies may file separate IRPs.',
    CONSTRAINT pk_irp_submission PRIMARY KEY(`irp_submission_id`)
) COMMENT 'Master record for each Integrated Resource Plan (IRP) submission filed with the state PUC or energy authority. Captures plan cycle year, planning horizon (years), total forecasted peak demand (MW), resource portfolio mix (fossil, nuclear, renewable, DR, EE), RPS compliance percentage, preferred resource plan description, alternative scenarios evaluated, filing date, PUC acknowledgment date, and next update due date. Tracks the utilitys long-range resource adequacy planning obligations.';

CREATE OR REPLACE TABLE `power_and_utilities`.`regulatory`.`compliance_obligation` (
    `compliance_obligation_id` BIGINT COMMENT 'Unique surrogate identifier for each compliance obligation record in the registry. Primary key for the compliance_obligation data product.',
    `cost_center_id` BIGINT COMMENT 'Foreign key linking to finance.cost_center. Business justification: Compliance obligations are assigned to cost centers for execution, budget allocation, and expense tracking. Compliance managers allocate obligations to responsible cost centers for resource planning. ',
    `rps_program_id` BIGINT COMMENT 'Foreign key linking to regulatory.rps_program. Business justification: RPS programs create specific compliance obligations (annual REC procurement targets, carve-out requirements, reporting deadlines). The compliance_obligation.regulatory_program STRING field should be n',
    `applicability_scope` STRING COMMENT 'The utility business segment or operational area to which this obligation applies. Enables filtering of obligations relevant to specific business units (e.g., a NERC CIP standard applies to transmission; a PHMSA rule applies to gas_distribution; an EPA GHG rule may apply to generation).. Valid values are `generation|transmission|electric_distribution|gas_distribution|metering|all`',
    `asset_class_scope` STRING COMMENT 'The specific class of assets or infrastructure covered by this obligation (e.g., BES Cyber Systems, High Consequence Areas, Bulk Electric System, Natural Gas Transmission Pipeline, Generation Unit > 20 MW). Supports asset-level compliance mapping in the Enterprise Asset Management (EAM) system.',
    `audit_frequency` STRING COMMENT 'How frequently the governing body conducts formal audits or compliance reviews of this obligation. Informs internal audit scheduling and readiness preparation cycles (e.g., NERC conducts triennial audits for most reliability standards; EPA may conduct annual inspections for Title V permits).. Valid values are `annual|biennial|triennial|spot_check|event_driven|not_applicable`',
    `cfr_citation` STRING COMMENT 'The specific Code of Federal Regulations (CFR) citation for this obligation where applicable (e.g., 40 CFR Part 98, 49 CFR Part 192, 18 CFR Part 35). Provides the authoritative legal reference for the obligation and supports regulatory correspondence.',
    `compliance_frequency` STRING COMMENT 'How often the utility must demonstrate or report compliance with this obligation. continuous applies to always-on operational standards (e.g., NERC CIP controls); event_driven applies to obligations triggered by specific incidents or thresholds (e.g., outage reporting, spill notification). [ENUM-REF-CANDIDATE: continuous|annual|semi_annual|quarterly|monthly|event_driven|one_time — 7 candidates stripped; promote to reference product]',
    `compliance_notes` STRING COMMENT 'Free-text field for compliance staff to record observations, interpretations, open issues, regulatory guidance received, or other contextual information relevant to managing this obligation. Not a substitute for formal evidence documentation.',
    `compliance_owner` STRING COMMENT 'Name or employee identifier of the individual designated as the primary compliance owner responsible for managing and demonstrating compliance with this obligation. This person is accountable for evidence collection, status updates, and regulatory submissions.',
    `compliance_status` STRING COMMENT 'Current compliance posture of the utility with respect to this obligation. compliant indicates all requirements are met; non_compliant indicates a known gap or violation; under_review indicates an active assessment is in progress; pending indicates the obligation is not yet effective; exempt indicates a formal exemption has been granted; remediation indicates a corrective action plan is active.. Valid values are `compliant|non_compliant|under_review|pending|exempt|remediation`',
    `corrective_action_plan_status` STRING COMMENT 'Current status of any Corrective Action Plan (CAP) associated with this obligation. not_required when the utility is compliant; in_development when a CAP is being drafted following a finding; active when a CAP is approved and being executed; completed when all CAP milestones are closed; overdue when CAP milestones have been missed.. Valid values are `not_required|in_development|active|completed|overdue`',
    `created_timestamp` TIMESTAMP COMMENT 'The date and time when this compliance obligation record was first created in the compliance registry. Provides the audit trail for when the obligation was onboarded into the compliance management system.',
    `effective_date` DATE COMMENT 'The date on which this compliance obligation became or becomes legally binding and enforceable for the utility. For new regulatory rules, this is the compliance date published in the final rule or order.',
    `escalation_contact` STRING COMMENT 'Name or employee identifier of the senior manager or executive to be notified in the event of non-compliance, missed deadlines, or regulatory inquiries related to this obligation. Supports the escalation workflow in the compliance management process.',
    `evidence_location` STRING COMMENT 'The system, repository, or document management location where compliance evidence and supporting documentation for this obligation is stored (e.g., SharePoint path, document management system folder, NERC CMEP portal, EPA e-GGRT system). Enables auditors to quickly locate supporting evidence.',
    `evidence_retention_years` STRING COMMENT 'The number of years that compliance evidence, records, and documentation must be retained for this obligation as required by the governing body. Drives records management policy and data archival schedules (e.g., NERC CIP requires 3 years; FERC OATT requires 5 years; EPA GHG requires 3 years).',
    `expiration_date` DATE COMMENT 'The date on which this compliance obligation expires or is superseded, if applicable. Null for ongoing, open-ended obligations. Used to identify obligations that are no longer active and to manage obligation lifecycle transitions.',
    `ghg_reporting_applicable` BOOLEAN COMMENT 'Indicates whether this compliance obligation involves Greenhouse Gas (GHG) emissions reporting or monitoring requirements under EPA regulations (e.g., 40 CFR Part 98 Mandatory GHG Reporting Rule). Enables filtering of GHG-related obligations for environmental compliance reporting.',
    `governing_body` STRING COMMENT 'The regulatory authority or standards body that issued and enforces this compliance obligation (e.g., FERC, NERC, EPA, PHMSA, State PUC). Determines the jurisdictional authority and applicable enforcement mechanisms. [ENUM-REF-CANDIDATE: FERC|NERC|EPA|PHMSA|PUC|DOE|OSHA|IEEE|AGA|NARUC — 10 candidates stripped; promote to reference product]',
    `jurisdiction_state` STRING COMMENT 'Two-letter US state code for state-level obligations (e.g., CA, TX, NY). Null for federal obligations that apply across all jurisdictions. Used to filter obligations by state regulatory authority (PUC) for multi-state utilities.. Valid values are `^[A-Z]{2}$`',
    `last_assessment_date` DATE COMMENT 'The most recent date on which a formal compliance assessment, audit, or self-certification was completed for this obligation. Used to determine assessment currency and schedule the next review cycle.',
    `last_audit_date` DATE COMMENT 'The date of the most recent formal audit or compliance review conducted by the governing body for this obligation. Used to calculate time since last audit and anticipate the next audit window.',
    `last_filing_date` DATE COMMENT 'The date of the most recent regulatory submission, report, or filing made to the governing body in fulfillment of this obligation (e.g., last annual GHG report submitted to EPA, last NERC self-report filed). Supports audit trail and filing history tracking.',
    `last_updated_timestamp` TIMESTAMP COMMENT 'The date and time when this compliance obligation record was most recently modified. Tracks changes to obligation status, ownership, due dates, or other attributes and supports change management auditing.',
    `nerc_violation_risk_factor` STRING COMMENT 'The Violation Risk Factor (VRF) assigned by NERC to this reliability standard requirement, indicating the potential impact of non-compliance on the reliability of the Bulk Electric System (BES). Applicable only to NERC reliability standards; null for non-NERC obligations.. Valid values are `severe|high|medium|lower`',
    `nerc_violation_severity_level` STRING COMMENT 'The Violation Severity Level (VSL) category applicable to this NERC standard requirement, reflecting the degree of non-compliance (Lower, Medium, High, Severe). Used in conjunction with VRF to determine the base penalty amount under the NERC Sanction Guidelines. Null for non-NERC obligations.. Valid values are `severe|high|medium|lower`',
    `next_due_date` DATE COMMENT 'The next calendar date by which the utility must complete a compliance action, submit a report, or demonstrate adherence for this obligation. Drives compliance calendar scheduling and proactive alerting for upcoming deadlines.',
    `obligation_category` STRING COMMENT 'Functional category of the compliance obligation describing the nature of the required action. Supports compliance program segmentation and resource allocation across operational, reporting, recordkeeping, physical security, cybersecurity, financial, and environmental obligations. [ENUM-REF-CANDIDATE: operational|reporting|recordkeeping|physical|cybersecurity|financial|environmental — 7 candidates stripped; promote to reference product]',
    `obligation_code` STRING COMMENT 'Externally-known alphanumeric code or identifier for the compliance obligation, typically matching the regulatory standard or rule identifier (e.g., NERC CIP-014-3, 40 CFR 98, 49 CFR 192.605, FERC OATT Section 37). Serves as the business-facing reference key used in regulatory filings and correspondence.',
    `obligation_description` STRING COMMENT 'Detailed narrative description of the compliance obligation, including the specific requirements the utility must meet, the actions required, and any conditions or thresholds that trigger compliance activities. Provides context for compliance staff and auditors.',
    `obligation_name` STRING COMMENT 'Full descriptive name of the compliance obligation as published by the governing body (e.g., Physical Security of BES Cyber Systems, Mandatory GHG Reporting Rule, Pipeline Integrity Management in High Consequence Areas). Used as the human-readable label in dashboards and reports.',
    `obligation_type` STRING COMMENT 'High-level classification of the compliance obligation by regulatory domain. Drives routing to the appropriate compliance team and applicable tracking workflow. [ENUM-REF-CANDIDATE: reliability_standard|emissions_regulation|pipeline_safety|service_quality|tariff_requirement|environmental_permit|safety_regulation|reporting_requirement — promote to reference product]',
    `open_violation_count` STRING COMMENT 'The current number of open, unresolved violations or findings associated with this compliance obligation. A value greater than zero triggers escalation workflows and corrective action plan (CAP) tracking. Sourced from the compliance management system.',
    `pbr_linked` BOOLEAN COMMENT 'Indicates whether this compliance obligation is linked to a Performance-Based Ratemaking (PBR) mechanism where non-compliance or underperformance results in financial incentives or penalties applied to the utilitys revenue requirement. Connects compliance tracking to rate case outcomes.',
    `penalty_exposure_usd` DECIMAL(18,2) COMMENT 'The maximum potential monetary penalty per day or per violation that the utility could face for non-compliance with this obligation, expressed in US dollars. Used for risk prioritization and materiality assessment in the compliance program. For NERC violations, this reflects the NERC Sanction Guidelines maximum.',
    `risk_priority` STRING COMMENT 'The assessed risk priority level for this obligation, reflecting the combination of likelihood of non-compliance and severity of consequences (financial penalty, operational impact, reputational harm). Used to prioritize compliance resources and management attention.. Valid values are `critical|high|medium|low`',
    `saidi_saifi_applicable` BOOLEAN COMMENT 'Indicates whether this compliance obligation involves electric distribution service quality metrics including System Average Interruption Duration Index (SAIDI), System Average Interruption Frequency Index (SAIFI), or Customer Average Interruption Duration Index (CAIDI) targets set by the state PUC. Enables filtering of service quality obligations.',
    `self_report_required` BOOLEAN COMMENT 'Indicates whether the utility is required to proactively self-report violations or non-compliance events to the governing body for this obligation. True for NERC standards with mandatory self-reporting under the CMEP; False for obligations where reporting is only required upon regulatory request.',
    `standard_version` STRING COMMENT 'The version or revision number of the regulatory standard or rule that this obligation is based on (e.g., CIP-014-3, Revision 2, 40 CFR 98 as amended 2023). Critical for tracking when standards are updated and ensuring the utility is complying with the current version.',
    `tariff_section_reference` STRING COMMENT 'The specific tariff section, schedule, or Open Access Transmission Tariff (OATT) provision that this obligation is associated with, where applicable (e.g., OATT Section 37, Rate Schedule No. 4, General Service Tariff Rule 15). Links compliance obligations to the utilitys filed tariffs.',
    CONSTRAINT pk_compliance_obligation PRIMARY KEY(`compliance_obligation_id`)
) COMMENT 'Master record for each ongoing regulatory compliance obligation the utility must fulfill — including NERC reliability standards (CIP, FAC, MOD, PRC), EPA emissions regulations (Clean Air Act, GHG reporting rule), PHMSA pipeline safety rules (49 CFR 192), PUC service quality standards (SAIDI, SAIFI, CAIDI targets), and FERC OATT requirements. Captures standard/rule identifier, governing body, obligation type, compliance frequency (annual, quarterly, event-driven, continuous), responsible business unit, current compliance status (compliant, non-compliant, under review), evidence retention requirements, next due date, and escalation contacts. Serves as the compliance obligation registry — the authoritative list of everything the utility must comply with and when.';

CREATE OR REPLACE TABLE `power_and_utilities`.`regulatory`.`compliance_event` (
    `compliance_event_id` BIGINT COMMENT 'Unique surrogate identifier for each compliance event record in the regulatory domain. Primary key for the compliance_event data product.',
    `compliance_obligation_id` BIGINT COMMENT 'Reference to the parent compliance obligation that this event fulfills, violates, or documents. Links the event to the specific regulatory requirement being tracked.',
    `corrective_action_plan_id` BIGINT COMMENT 'Reference to the corrective action plan (CAP) associated with this compliance event, applicable when the event type is a violation, audit finding, or deficiency requiring remediation.',
    `cost_center_id` BIGINT COMMENT 'Foreign key linking to finance.cost_center. Business justification: Compliance events incur costs (penalties, remediation, legal fees) charged to specific cost centers. Finance allocates compliance expenses to responsible cost centers for budget tracking, variance ana',
    `docket_id` BIGINT COMMENT 'Reference to the regulatory docket or proceeding associated with this compliance event, such as a FERC docket, PUC proceeding, or NERC enforcement action.',
    `master_id` BIGINT COMMENT 'Reference to the specific generation, transmission, or distribution asset (e.g., generator unit, transmission line, substation, gas pipeline segment) associated with this compliance event. Links to the asset management system (Oracle WAM or IBM Maximo) for asset-level compliance tracking.',
    `employee_id` BIGINT COMMENT 'Reference to the employee or compliance officer designated as the accountable party for this compliance event. Links to the workforce/HR system (SuccessFactors or Workday) for personnel accountability and regulatory contact identification.',
    `closed_indicator` BOOLEAN COMMENT 'Indicates whether this compliance event has been formally closed by the regulatory authority or internal compliance function. True = closed/resolved with no further action required; False = open and active. Supports compliance dashboard reporting and open-item tracking.',
    `closure_date` DATE COMMENT 'Date on which this compliance event was formally closed by the regulatory authority or internal compliance function. Null if the event remains open. Used for compliance lifecycle reporting and regulatory audit trail documentation.',
    `completion_date` DATE COMMENT 'Date on which the compliance event was fully completed — e.g., evidence successfully submitted, corrective action verified as complete, or penalty paid. Null if the event is still in progress. Used to assess timeliness against due_date.',
    `compliance_domain` STRING COMMENT 'High-level regulatory domain to which this compliance event belongs. reliability = NERC bulk electric system reliability; environmental = EPA GHG/emissions; market = FERC wholesale market rules; safety = OSHA/PHMSA worker and pipeline safety; tariff = OATT/tariff compliance; rate_case = PUC rate proceeding; gas_pipeline = PHMSA gas distribution/transmission; financial = SOX/GAAP financial reporting. [ENUM-REF-CANDIDATE: reliability|environmental|market|safety|tariff|rate_case|gas_pipeline|financial — promote to reference product]',
    `compliance_status` STRING COMMENT 'Current compliance standing for this event. compliant = obligation met; deficient = obligation not met or violation identified; remediated = deficiency corrected and verified; under_review = regulator or internal team evaluating status; pending = awaiting evidence or determination.. Valid values are `compliant|deficient|remediated|under_review|pending`',
    `created_timestamp` TIMESTAMP COMMENT 'Timestamp when this compliance event record was first created in the system, including timezone offset. Supports audit trail requirements and Silver layer data lineage tracking in the Databricks Lakehouse.',
    `due_date` DATE COMMENT 'Regulatory or internal deadline by which this compliance event must be completed — e.g., the filing deadline for evidence submission, the deadline for corrective action completion, or the response deadline for a violation notice. Critical for compliance calendar management.',
    `emission_quantity` DECIMAL(18,2) COMMENT 'Quantity of regulated emissions associated with this compliance event, expressed in the applicable unit (tons, metric tons CO2e, MCF). Used for EPA GHG reporting compliance verification and environmental penalty calculations under the Clean Air Act.',
    `emission_quantity_unit` STRING COMMENT 'Unit of measure for the emission_quantity field. short_tons = US short tons; metric_tons_co2e = metric tons CO2 equivalent (standard GHG reporting unit); MCF = thousand cubic feet (gas); MWh = megawatt-hours (for heat rate compliance).. Valid values are `short_tons|metric_tons_co2e|MCF|MWh`',
    `event_date` DATE COMMENT 'The principal real-world date on which the compliance event occurred — e.g., the date evidence was submitted, the date a violation was identified, the date a self-report was filed, or the date an audit finding was issued. Distinct from record audit timestamps.',
    `event_description` STRING COMMENT 'Narrative description of the compliance event, including the nature of the activity, the specific non-compliance condition identified, or the evidence submitted. Provides the human-readable context required for regulatory filings, audit documentation, and internal compliance reporting.',
    `event_number` STRING COMMENT 'Externally-known alphanumeric identifier assigned to this compliance event, used in regulatory correspondence, audit trails, and submissions to NERC, FERC, EPA, or PUC. Example: CE-2024-00123.',
    `event_timestamp` TIMESTAMP COMMENT 'Precise date and time the compliance event occurred or was recorded, including timezone offset. Used for exact sequencing of events within a compliance lifecycle, particularly for NERC real-time reliability events and FERC market compliance incidents.',
    `event_type` STRING COMMENT 'Classification of the compliance activity represented by this event. Values: evidence_submission (documentation submitted to regulator), self_report (voluntary self-disclosure of non-compliance), violation_notice (formal notice received from regulator), corrective_action (remediation activity undertaken), audit_finding (finding from regulatory or internal audit), penalty_assessment (monetary or operational penalty levied).. Valid values are `evidence_submission|self_report|violation_notice|corrective_action|audit_finding|penalty_assessment`',
    `evidence_reference` STRING COMMENT 'Document identifier, file path, or external system reference pointing to the evidence package submitted or associated with this compliance event. Examples: document management system ID, NERC COMS submission reference, EPA CDX submission ID, or SharePoint document URL.',
    `facility_name` STRING COMMENT 'Name of the generation plant, substation, transmission facility, or gas distribution facility associated with this compliance event. Provides human-readable facility context for regulatory reporting and audit documentation.',
    `ghg_emission_type` STRING COMMENT 'Type of greenhouse gas or regulated air emission associated with this compliance event, applicable for EPA environmental compliance events. CO2 = carbon dioxide; CH4 = methane; N2O = nitrous oxide; SF6 = sulfur hexafluoride (electrical equipment); NOx = nitrogen oxides; SOx = sulfur oxides.. Valid values are `CO2|CH4|N2O|SF6|NOx|SOx`',
    `jurisdiction_state` STRING COMMENT 'Two-letter US state code identifying the state regulatory jurisdiction applicable to this compliance event. Relevant for PUC-regulated activities. Null for federal-only events (FERC, NERC, EPA).. Valid values are `^[A-Z]{2}$`',
    `nerc_region` STRING COMMENT 'The NERC Regional Entity (RE) with compliance monitoring and enforcement authority over this event. Examples: WECC (Western Electricity Coordinating Council), SERC, RFC, MRO, NPCC, TRE. Applicable for NERC reliability compliance events. Null for non-NERC events.',
    `penalty_amount` DECIMAL(18,2) COMMENT 'Monetary penalty assessed against the utility for this compliance event, denominated in US dollars. Applicable when event_type is penalty_assessment. Includes NERC Notice of Penalty (NOP) amounts, EPA civil penalties, FERC civil penalties, and PUC-imposed fines. Zero if no penalty was assessed.',
    `penalty_paid_date` DATE COMMENT 'Date on which the assessed penalty was remitted to the regulatory authority. Null if penalty has not been paid or no penalty was assessed. Used for financial reconciliation and regulatory closure confirmation.',
    `penalty_paid_indicator` BOOLEAN COMMENT 'Indicates whether the assessed penalty has been paid to the regulatory authority. True = penalty paid; False = penalty outstanding or not yet assessed. Applicable only when penalty_amount is greater than zero.',
    `recurrence_indicator` BOOLEAN COMMENT 'Indicates whether this compliance event represents a repeat or recurring violation of the same regulatory standard. True = recurrence; False = first occurrence. Recurrence is an aggravating factor in NERC CMEP and EPA penalty determinations.',
    `regulator_case_number` STRING COMMENT 'The case, docket, or tracking number assigned by the regulatory authority (NERC, FERC, EPA, PUC) to this compliance event or associated enforcement action. Used for cross-referencing with regulator records and official correspondence.',
    `regulator_response_notes` STRING COMMENT 'Notes or summary of the regulatory authoritys response to this compliance event, including acceptance of evidence, issuance of a Notice of Penalty (NOP), approval of a corrective action plan, or closure of the enforcement action. Captures key communications from NERC, FERC, EPA, or PUC.',
    `regulatory_body` STRING COMMENT 'The governing regulatory authority to which this compliance event pertains. Identifies the jurisdiction and oversight body: NERC (reliability), FERC (wholesale markets/transmission), EPA (environmental), PUC (state retail regulation), PHMSA (gas pipeline safety), OSHA (worker safety), DOE (federal energy policy), NARUC (state commission coordination). [ENUM-REF-CANDIDATE: NERC|FERC|EPA|PUC|PHMSA|OSHA|DOE|NARUC — 8 candidates stripped; promote to reference product]',
    `regulatory_standard_ref` STRING COMMENT 'The specific regulatory standard, rule, tariff provision, or statute that this compliance event relates to. Examples: NERC Reliability Standard CIP-007-6, FERC Order 2222, EPA 40 CFR Part 75, State PUC General Order 95. Provides the authoritative citation for audit and enforcement purposes.',
    `responsible_party_name` STRING COMMENT 'Name of the internal organizational unit, department, or named individual accountable for this compliance event — e.g., the team responsible for submitting evidence, executing a corrective action, or responding to a violation notice. Used for accountability tracking and regulatory correspondence.',
    `risk_level` STRING COMMENT 'Risk severity classification of this compliance event based on potential impact to grid reliability, public safety, environmental harm, or financial exposure. critical = immediate threat to BES reliability or public safety; high = significant regulatory exposure; medium = moderate risk; low = minor administrative non-compliance. Aligns with NERC violation risk factor (VRF) methodology.. Valid values are `critical|high|medium|low`',
    `rto_iso_name` STRING COMMENT 'Name of the Regional Transmission Organization (RTO) or Independent System Operator (ISO) relevant to this compliance event, such as PJM, MISO, CAISO, SPP, ERCOT, NYISO, or ISO-NE. Applicable for FERC market compliance and OATT-related events.',
    `self_report_indicator` BOOLEAN COMMENT 'Indicates whether this compliance event was voluntarily self-reported by the utility to the regulator prior to detection. True = self-reported; False = identified by regulator or third party. Self-reporting is a mitigating factor in NERC CMEP and EPA penalty calculations.',
    `submission_method` STRING COMMENT 'Method by which evidence or filings associated with this compliance event were submitted to the regulatory authority. electronic = NERC COMS, EPA CDX, FERC eFiling; portal = state PUC e-filing portal; paper = physical filing; email = direct email submission.. Valid values are `electronic|paper|portal|email`',
    `updated_timestamp` TIMESTAMP COMMENT 'Timestamp when this compliance event record was last modified, including timezone offset. Tracks the most recent update for change management, audit trail, and Silver layer incremental processing in the Databricks Lakehouse.',
    `violation_end_date` DATE COMMENT 'Date on which the non-compliance condition was resolved or the violation ceased, as verified by the utility or regulator. Null if the violation is ongoing. Used with violation_start_date to determine violation duration for penalty calculation.',
    `violation_risk_factor` STRING COMMENT 'NERC-defined Violation Risk Factor (VRF) assigned to the reliability standard requirement associated with this compliance event. Values per NERC methodology: high, medium, lower. Used in NERC CMEP penalty matrix calculations. Null for non-NERC events.. Valid values are `high|medium|lower`',
    `violation_severity_level` STRING COMMENT 'NERC-defined Violation Severity Level (VSL) for this compliance event, reflecting the degree of non-compliance with the applicable reliability standard requirement. Values per NERC methodology: severe, high, medium, lower. Used in NERC CMEP penalty matrix. Null for non-NERC events.. Valid values are `severe|high|medium|lower`',
    `violation_start_date` DATE COMMENT 'Date on which the non-compliance condition began, as determined by the utility or regulator. Applicable when event_type is violation_notice, self_report, or audit_finding. Used to calculate violation duration for penalty assessment under NERC CMEP and EPA enforcement policies.',
    CONSTRAINT pk_compliance_event PRIMARY KEY(`compliance_event_id`)
) COMMENT 'Transactional record of each compliance activity, evidence submission, or violation event associated with a regulatory compliance obligation. Captures event type (evidence submission, self-report, violation notice, corrective action, audit finding, penalty assessment), event date, obligation reference, responsible party, compliance status (compliant, deficient, remediated), penalty amount if applicable, and corrective action plan reference. Provides the audit trail for demonstrating compliance to NERC, EPA, PUC, and FERC.';

CREATE OR REPLACE TABLE `power_and_utilities`.`regulatory`.`emissions_report` (
    `emissions_report_id` BIGINT COMMENT 'Unique surrogate identifier for each emissions report record in the Silver Layer lakehouse. Primary key for this transactional entity.',
    `compliance_event_id` BIGINT COMMENT 'Foreign key linking to regulatory.compliance_event. Business justification: Emissions reports serve as evidence for compliance events. When a compliance_event is related to emissions (e.g., GHG reporting, violation of emission limits), the emissions_report should reference th',
    `compliance_obligation_id` BIGINT COMMENT 'Foreign key linking to regulatory.compliance_obligation. Business justification: Emissions reports fulfill specific compliance obligations (e.g., EPA GHG reporting, state air quality reporting). Each emissions_report should reference the compliance_obligation it satisfies. This cr',
    `cost_center_id` BIGINT COMMENT 'Foreign key linking to finance.cost_center. Business justification: Emissions monitoring and reporting costs are allocated to operational cost centers (generation facilities, transmission districts). Environmental compliance costs must be tracked by cost center for FE',
    `der_interconnection_id` BIGINT COMMENT 'Foreign key linking to distribution.der_interconnection. Business justification: DER systems offset emissions and generate RECs tracked in emissions reports. Environmental compliance linkage: attributing emission reductions to specific DER interconnections for GHG reporting and RE',
    `facility_id` BIGINT COMMENT 'Reference to the generation facility or plant from which emissions are reported. Links to the asset/facility master record.',
    `generating_unit_id` BIGINT COMMENT 'Reference to the specific generation unit (boiler, turbine, combustion unit) within the facility for which emissions are reported. A facility may have multiple reportable units.',
    `original_report_emissions_report_id` BIGINT COMMENT 'Reference to the original emissions report record that this amended report supersedes. Populated only when amendment_indicator = True. Enables lineage tracking of report corrections and restatements.',
    `rec_transaction_id` BIGINT COMMENT 'Identifier of the Renewable Energy Certificate (REC) retirement transaction linked to this emissions report, used to demonstrate RPS compliance and offset GHG obligations. References the REC tracking system (e.g., WREGIS, PJM-GATS, M-RETS).',
    `agency_confirmation_number` STRING COMMENT 'Confirmation or acknowledgment number issued by the regulatory agency (EPA, state air agency) upon successful receipt and acceptance of the emissions report submission. Used as proof of filing for compliance audits.',
    `allowance_type` STRING COMMENT 'Cap-and-trade or allowance program under which this emissions report is filed. SO2_ARP = EPA Acid Rain Program; NOx_NBP = NOx Budget Trading Program; CSAPR_NOx / CSAPR_SO2 = Cross-State Air Pollution Rule; RGGI_CO2 = Regional Greenhouse Gas Initiative; state_cap = state-specific cap program. [ENUM-REF-CANDIDATE: SO2_ARP|NOx_NBP|CSAPR_NOx|CSAPR_SO2|RGGI_CO2|state_cap|CA_AB32|other — promote to reference product]. Valid values are `SO2_ARP|NOx_NBP|CSAPR_NOx|CSAPR_SO2|RGGI_CO2|state_cap`',
    `allowances_surrendered` DECIMAL(18,2) COMMENT 'Number of emissions allowances surrendered or retired to cover the reported emissions quantity under the applicable cap-and-trade program (e.g., EPA Acid Rain Program SO2 allowances, RGGI CO2 allowances). One allowance typically equals one ton of the regulated pollutant.',
    `amendment_indicator` BOOLEAN COMMENT 'Indicates whether this emissions report is an amendment (restatement) of a previously submitted report. True = this is an amended filing; False = original submission. Supports audit trail and regulatory compliance tracking.',
    `cems_system_code` STRING COMMENT 'Identifier of the Continuous Emissions Monitoring System (CEMS) used to measure emissions for this report, as registered with EPA. Applicable when measurement_methodology = CEMS. Supports audit trail and CEMS certification tracking.',
    `co2e_quantity_metric_tons` DECIMAL(18,2) COMMENT 'Total emissions expressed as metric tons of carbon dioxide equivalent (CO2e), calculated using IPCC global warming potential (GWP) factors. Used for aggregate GHG inventory reporting, RPS compliance, and SEC/state climate disclosure obligations.',
    `created_timestamp` TIMESTAMP COMMENT 'Timestamp when this emissions report record was first created in the system, in ISO 8601 format (yyyy-MM-ddTHH:mm:ss.SSSXXX). Supports audit trail and data lineage tracking in the Silver Layer lakehouse.',
    `emissions_intensity_lbs_per_mwh` DECIMAL(18,2) COMMENT 'Emissions rate expressed as pounds of pollutant per megawatt-hour (MWh) of gross electricity generated during the reporting period. Key performance indicator for environmental compliance, RPS tracking, and EPA rate-based standards under Clean Power Plan successor rules.',
    `emissions_quantity_tons` DECIMAL(18,2) COMMENT 'Total mass of the reported pollutant emitted during the reporting period, expressed in short tons (US tons). This is the primary quantitative result for the emissions report, as required by EPA CAMD and state air quality agency submissions.',
    `emissions_quantity_unit` STRING COMMENT 'Unit of measure for the reported emissions quantity. Short tons is the standard for EPA CAMD reporting; metric tons (MT) is used for GHG Protocol and international reporting; lbs and kg may be used for state-level criteria pollutant reporting.. Valid values are `short_tons|metric_tons|lbs|kg`',
    `epa_facility_code` STRING COMMENT 'EPA-assigned facility identifier used in the Facility Registry Service (FRS) and Clean Air Markets Division (CAMD) systems. Required for all EPA emissions submissions under 40 CFR Part 75 and Part 98.. Valid values are `^[A-Z0-9]{1,20}$`',
    `epa_unit_code` STRING COMMENT 'EPA-assigned unit identifier for the specific combustion or generation unit within the facility, as registered in the EPA Clean Air Markets Division (CAMD) Business System. Used for unit-level emissions tracking and compliance.',
    `fuel_consumption_quantity` DECIMAL(18,2) COMMENT 'Total quantity of fuel consumed during the reporting period, expressed in the unit appropriate to the fuel type (e.g., MCF for natural gas, short tons for coal, barrels for oil). Used in fuel-factor emissions calculations and fuel adjustment clause (FAC) cost recovery.',
    `fuel_consumption_unit` STRING COMMENT 'Unit of measure for the fuel consumption quantity. MCF = Thousand Cubic Feet (natural gas); MMBtu = Million British Thermal Units; short_tons (coal); barrels or gallons (oil/liquid fuels).. Valid values are `MCF|MMBtu|short_tons|barrels|gallons`',
    `fuel_type` STRING COMMENT 'Primary fuel type combusted at the generation unit during the reporting period. Determines applicable emission factors for fuel-factor methodology and influences GHG scope classification. [ENUM-REF-CANDIDATE: natural_gas|coal|oil|nuclear|biomass|coal_blend|waste_coal|petroleum_coke|other — promote to reference product]. Valid values are `natural_gas|coal|oil|nuclear|biomass|other`',
    `ghg_scope` STRING COMMENT 'GHG Protocol scope classification for the reported emissions. Scope 1 = direct emissions from owned/controlled sources (combustion); Scope 2 = indirect emissions from purchased electricity/heat; Scope 3 = other indirect value chain emissions. Required for corporate GHG inventory and SEC climate disclosure.. Valid values are `scope_1|scope_2|scope_3`',
    `gross_generation_mwh` DECIMAL(18,2) COMMENT 'Total gross electricity generation in megawatt-hours (MWh) produced by the unit or facility during the reporting period. Used as the denominator for emissions intensity calculations and for cross-referencing with EIA generation reporting.',
    `heat_input_mmbtu` DECIMAL(18,2) COMMENT 'Total heat input to the combustion unit during the reporting period, expressed in million British thermal units (MMBtu). Used for fuel-factor emissions calculations and heat rate performance analysis. Required field in EPA CAMD quarterly submissions.',
    `measurement_methodology` STRING COMMENT 'Method used to quantify emissions for this report. CEMS = Continuous Emissions Monitoring System (direct measurement per 40 CFR Part 75); fuel_factor = EPA-approved fuel emission factor method; mass_balance = material balance calculation; engineering_estimate = approved engineering estimation method for missing data substitution.. Valid values are `CEMS|fuel_factor|mass_balance|engineering_estimate`',
    `missing_data_hours` STRING COMMENT 'Number of operating hours during the reporting period for which CEMS data was unavailable and EPA-approved missing data substitution procedures were applied per 40 CFR Part 75 Subpart D. Regulatory threshold triggers enhanced scrutiny if exceeded.',
    `nox_rate_lbs_per_mmbtu` DECIMAL(18,2) COMMENT 'Nitrogen oxides (NOx) emission rate expressed as pounds per million British thermal units (lbs/MMBtu) of heat input. Required for EPA CAMD quarterly reporting and NOx Budget Trading Program compliance. Distinct from the aggregate emissions_intensity_lbs_per_mwh field.',
    `operating_hours` STRING COMMENT 'Total number of hours the generation unit operated during the reporting period. Used to calculate emissions rates, validate CEMS data completeness, and support EPA quarterly report submissions.',
    `pollutant_type` STRING COMMENT 'Type of greenhouse gas (GHG) or criteria pollutant being reported. CO2 = Carbon Dioxide, CH4 = Methane, N2O = Nitrous Oxide, NOx = Nitrogen Oxides, SO2 = Sulfur Dioxide, particulates = particulate matter (PM2.5/PM10), CO2e = Carbon Dioxide Equivalent (aggregated GHG). [ENUM-REF-CANDIDATE: CO2|CH4|N2O|NOx|SO2|particulates|CO2e|Hg|HCl|HF — promote to reference product]',
    `regulatory_deadline_date` DATE COMMENT 'Regulatory deadline by which this emissions report must be submitted to the applicable agency. Used to monitor on-time compliance and flag late submissions for regulatory risk management.',
    `report_notes` STRING COMMENT 'Free-text field for supplemental notes, explanations of anomalies, missing data justifications, or regulatory correspondence references associated with this emissions report. Used by compliance staff to document context for auditors and regulators.',
    `report_number` STRING COMMENT 'Externally-known business identifier assigned to this emissions report submission, used for tracking with EPA or state air quality agency. Corresponds to the submission tracking number in EPAs Electronic Reporting Tool or state equivalent.',
    `reporting_agency` STRING COMMENT 'Regulatory agency or body to which this emissions report is submitted. EPA = U.S. Environmental Protection Agency (federal); state_air_agency = state environmental/air quality agency; FERC = Federal Energy Regulatory Commission; NERC = North American Electric Reliability Corporation; DOE_EIA = U.S. Department of Energy / Energy Information Administration.. Valid values are `EPA|state_air_agency|FERC|NERC|DOE_EIA`',
    `reporting_period_end_date` DATE COMMENT 'End date of the emissions reporting period. Combined with reporting_period_start_date to define the measurement window for this report.',
    `reporting_period_start_date` DATE COMMENT 'Start date of the emissions reporting period (e.g., calendar year start, quarter start, or compliance period start). Combined with reporting_period_end_date to define the measurement window.',
    `reporting_period_type` STRING COMMENT 'Classification of the reporting period granularity: annual (calendar year), quarterly, monthly, or compliance_period (custom regulatory compliance window). Determines submission frequency and applicable regulatory deadlines.. Valid values are `annual|quarterly|monthly|compliance_period`',
    `so2_rate_lbs_per_mmbtu` DECIMAL(18,2) COMMENT 'Sulfur dioxide (SO2) emission rate expressed as pounds per million British thermal units (lbs/MMBtu) of heat input. Required for EPA Acid Rain Program (ARP) compliance and CAMD quarterly reporting under 40 CFR Part 75.',
    `state_facility_permit_number` STRING COMMENT 'State-issued air quality operating permit number (Title V or minor source permit) for the facility, as assigned by the state environmental or air quality agency. Required for state-level emissions reporting submissions.',
    `submission_date` DATE COMMENT 'Date on which the emissions report was submitted to the regulatory agency. Used to verify compliance with regulatory submission deadlines and to support prudency reviews.',
    `submission_status` STRING COMMENT 'Current lifecycle status of the emissions report submission to the regulatory agency. draft = in preparation; submitted = transmitted to agency; accepted = agency confirmed receipt and validity; rejected = agency returned with errors; under_review = agency is reviewing; amended = resubmitted after correction.. Valid values are `draft|submitted|accepted|rejected|under_review|amended`',
    `updated_timestamp` TIMESTAMP COMMENT 'Timestamp when this emissions report record was last modified, in ISO 8601 format (yyyy-MM-ddTHH:mm:ss.SSSXXX). Used to detect amendments, data corrections, and track the most recent state of the record in the Silver Layer.',
    `verification_date` DATE COMMENT 'Date on which third-party verification of the emissions report was completed. Populated when verified_indicator = True. Used to confirm verification was completed prior to regulatory submission deadline.',
    `verified_indicator` BOOLEAN COMMENT 'Indicates whether the emissions data in this report has been independently verified by a third-party verifier, as required under certain state GHG programs (e.g., California AB 32, RGGI). True = verified; False = not yet verified or not required.',
    `verifier_name` STRING COMMENT 'Name of the accredited third-party verification body that reviewed and verified the emissions data. Populated when verified_indicator = True. Required for California ARB and RGGI compliance submissions.',
    CONSTRAINT pk_emissions_report PRIMARY KEY(`emissions_report_id`)
) COMMENT 'Transactional record of GHG and criteria pollutant emissions reported per generation unit or facility per reporting period. Captures facility/unit identifier, reporting period, pollutant type (CO2, NOx, SO2, CH4, particulates), emissions quantity (tons), emissions intensity (lbs/MWh), measurement methodology (CEMS, fuel-factor), EPA facility ID, REC retirement linkage, and submission status to EPA or state air quality agency. Supports GHG compliance, RPS tracking, and environmental regulatory reporting obligations.';

CREATE OR REPLACE TABLE `power_and_utilities`.`regulatory`.`prudency_review` (
    `prudency_review_id` BIGINT COMMENT 'Unique surrogate identifier for each prudency review or management audit record in the Silver Layer lakehouse. Primary key for this entity. Entity role: TRANSACTION_HEADER — a discrete regulatory business event with a defined lifecycle initiated by a PUC or FERC to evaluate the reasonableness of utility expenditures.',
    `capex_project_id` BIGINT COMMENT 'Reference identifier for the capital project or work order in the Enterprise Asset Management (EAM) system (Oracle WAM or IBM Maximo) whose expenditures are under prudency review. Enables traceability from regulatory review to the originating capital project record.',
    `cost_recovery_mechanism_id` BIGINT COMMENT 'Foreign key linking to regulatory.cost_recovery_mechanism. Business justification: Prudency reviews evaluate whether costs recovered through cost recovery mechanisms were prudently incurred. The prudency_review table currently has cost_recovery_mechanism as STRING; this should be no',
    `cpcn_application_id` BIGINT COMMENT 'Foreign key linking to regulatory.cpcn_application. Business justification: Prudency reviews can evaluate CPCN projects to determine if costs were prudently incurred. When a prudency_review is evaluating a CPCN project, it should reference the cpcn_application. This is nullab',
    `docket_id` BIGINT COMMENT 'Reference to the regulatory docket that triggered or is associated with this prudency review. Links to the docket master record in the regulatory domain.',
    `commission_order_id` BIGINT COMMENT 'Foreign key linking to regulatory.commission_order. Business justification: Prudency reviews conclude with a final determination issued via commission order. The prudency_review table should reference the commission_order that contains the final determination. This links the ',
    `rate_case_id` BIGINT COMMENT 'Reference to the rate case proceeding in which the results of this prudency review will be or have been incorporated for revenue requirement determination. Links to the rate_case product in the regulatory domain.',
    `financial_period_id` BIGINT COMMENT 'Foreign key linking to finance.financial_period. Business justification: Prudency reviews examine costs incurred during specific financial periods (review_period_start/end_date). Regulatory affairs and finance jointly analyze expenditures by financial period to prepare pru',
    `afudc_impact_amt` DECIMAL(18,2) COMMENT 'Dollar amount of Allowance for Funds Used During Construction (AFUDC) associated with the capital expenditures under review. Relevant for capital project prudency reviews where AFUDC capitalization is also subject to reasonableness evaluation.',
    `appeal_filing_date` DATE COMMENT 'Date on which the appeal or request for rehearing of the prudency determination was filed. Null if appeal_indicator is False.',
    `appeal_indicator` BOOLEAN COMMENT 'Indicates whether the utility or any party has filed an appeal or request for rehearing of the final prudency determination. True if an appeal is pending or has been filed; False otherwise.',
    `approved_recovery_amt` DECIMAL(18,2) COMMENT 'Final dollar amount of expenditures approved for cost recovery from ratepayers per the final regulatory determination. Equals total_expenditure_under_review_amt minus disallowed_amt. Satisfies TRANSACTION_HEADER MONETARY_TRIPLET net total category.',
    `capex_under_review_amt` DECIMAL(18,2) COMMENT 'Total capital expenditure (CAPEX) amount in USD submitted for prudency review. Represents the gross plant investment being evaluated for reasonableness and cost recovery eligibility. Null if review covers only O&M or fuel costs.',
    `created_timestamp` TIMESTAMP COMMENT 'Timestamp when this prudency review record was first captured in the data platform (Silver Layer ingestion). Formatted as yyyy-MM-ddTHH:mm:ss.SSSXXX. Satisfies TRANSACTION_HEADER RECORD_AUDIT_CREATED category.',
    `currency_code` STRING COMMENT 'ISO 4217 three-letter currency code for all monetary amounts in this prudency review record (e.g., USD). Satisfies TRANSACTION_HEADER MONETARY_TRIPLET currency code requirement.. Valid values are `^[A-Z]{3}$`',
    `disallowed_amt` DECIMAL(18,2) COMMENT 'Final dollar amount of expenditures disallowed from rate base or cost recovery per the final regulatory determination. Represents the imprudent portion that the utility must absorb and cannot recover from ratepayers. Satisfies TRANSACTION_HEADER MONETARY_TRIPLET adjustment category.',
    `effective_date` DATE COMMENT 'Date on which the final prudency determination becomes effective for rate base inclusion or cost recovery purposes. May differ from the final determination date if the order specifies a prospective effective date.',
    `final_determination` STRING COMMENT 'The final regulatory determination on the prudency of the expenditures under review. Prudent allows full cost recovery; Imprudent disallows costs from rate base; Partially Prudent allows partial recovery; Settled indicates a negotiated resolution; Withdrawn indicates the review was dropped.. Valid values are `prudent|imprudent|partially_prudent|settled|withdrawn`',
    `final_determination_date` DATE COMMENT 'Date on which the regulatory body issued its final order or determination on the prudency review. Marks the conclusion of the review proceeding and triggers cost recovery or disallowance accounting entries.',
    `fuel_cost_under_review_amt` DECIMAL(18,2) COMMENT 'Total fuel procurement cost in USD submitted for prudency review under a Fuel Adjustment Clause (FAC) proceeding. Covers fossil fuel, purchased power, and gas supply costs. Null if review does not involve fuel cost prudency.',
    `initiation_date` DATE COMMENT 'The date on which the prudency review was formally initiated by the regulatory body or triggered by a docket filing. Represents the principal real-world business event timestamp (date precision). Satisfies TRANSACTION_HEADER BUSINESS_EVENT_TIMESTAMP category.',
    `intervenor_indicator` BOOLEAN COMMENT 'Indicates whether one or more intervenors (e.g., ratepayer advocates, industrial customers, environmental groups) formally participated in the prudency review proceeding. True if intervenors are present; False if the review is conducted solely by commission staff.',
    `jurisdiction_state` STRING COMMENT 'Two-letter US state abbreviation (USPS standard) identifying the state PUC jurisdiction for this prudency review. Null for federal FERC reviews. Used for multi-state utility regulatory reporting segmentation.. Valid values are `^[A-Z]{2}$`',
    `opex_under_review_amt` DECIMAL(18,2) COMMENT 'Total operating expenditure (OPEX) / O&M cost amount in USD submitted for prudency review. Represents the operating costs being evaluated for reasonableness. Null if review covers only capital or fuel costs.',
    `preliminary_disallowed_amt` DECIMAL(18,2) COMMENT 'Dollar amount of expenditures preliminarily identified as imprudent and proposed for disallowance from rate base or cost recovery by the reviewing body. May be revised in the final determination.',
    `preliminary_finding` STRING COMMENT 'The initial finding issued by the reviewing body prior to the final determination. Indicates whether expenditures appear prudent, imprudent, or partially prudent based on preliminary staff analysis. May differ from the final determination after hearings and rebuttal testimony.. Valid values are `prudent|imprudent|partially_prudent|inconclusive|pending`',
    `preliminary_finding_date` DATE COMMENT 'Date on which the reviewing body issued its preliminary finding. Used to track regulatory timeline milestones and compliance with procedural deadlines.',
    `regulatory_jurisdiction` STRING COMMENT 'Jurisdictional level of the regulatory body overseeing this prudency review. Federal indicates FERC jurisdiction; State indicates a state PUC; Local indicates a municipal or county authority.. Valid values are `federal|state|local`',
    `review_notes` STRING COMMENT 'Free-text field for additional context, regulatory staff comments, utility responses, or procedural notes relevant to the prudency review. Used for internal tracking and regulatory correspondence documentation.',
    `review_number` STRING COMMENT 'Externally-known alphanumeric identifier assigned by the regulatory body or internal tracking system to uniquely reference this prudency review (e.g., PR-2024-0042). Used in regulatory correspondence, testimony, and filings. Satisfies TRANSACTION_HEADER BUSINESS_IDENTIFIER category.',
    `review_period_end_date` DATE COMMENT 'End date of the expenditure period under review. Defines the close of the time window for which costs are being evaluated for prudency.',
    `review_period_start_date` DATE COMMENT 'Start date of the expenditure period under review. Defines the beginning of the time window for which costs are being evaluated for prudency.',
    `review_status` STRING COMMENT 'Current lifecycle state of the prudency review workflow. Progresses from initiated through in-progress, preliminary finding, final determination, and closure. Satisfies TRANSACTION_HEADER LIFECYCLE_STATUS category.. Valid values are `initiated|in_progress|preliminary_finding_issued|final_determination_issued|closed|withdrawn`',
    `review_type` STRING COMMENT 'Classification of the prudency review by the category of expenditure under examination. Capital Project prudency evaluates CAPEX reasonableness; O&M Expenditure covers operating costs; Fuel Cost covers FAC-related fuel procurement; Storm Cost Recovery covers major storm restoration costs; General Management Audit covers broad operational spending. Satisfies TRANSACTION_HEADER LIFECYCLE_STATUS classification dimension.. Valid values are `capital_project|om_expenditure|fuel_cost|storm_cost_recovery|general_management_audit`',
    `reviewing_body` STRING COMMENT 'The party or organization conducting the prudency review — e.g., PUC Staff, FERC Staff, an independent auditor appointed by the commission, or Office of Attorney General staff. Satisfies TRANSACTION_HEADER PARTY_REFERENCE category (regulatory reviewer as the counterparty).. Valid values are `puc_staff|ferc_staff|independent_auditor|oag_staff|intervenor_consultant`',
    `reviewing_body_name` STRING COMMENT 'Full legal or organizational name of the entity conducting the prudency review (e.g., California Public Utilities Commission Division of Ratepayer Advocates, Navigant Consulting Inc.). Complements reviewing_body code with a human-readable label for reporting and correspondence.',
    `scope_description` STRING COMMENT 'Narrative description of the scope of the prudency review, including the specific projects, programs, time periods, and expenditure categories under examination. Provides context for regulatory testimony and rate case filings.',
    `settlement_date` DATE COMMENT 'Date on which the settlement agreement was executed or approved by the commission, if the prudency review was resolved through settlement. Null if settlement_indicator is False.',
    `settlement_indicator` BOOLEAN COMMENT 'Indicates whether the prudency review was resolved through a negotiated settlement agreement rather than a litigated final order. True if settled; False if resolved by contested commission order.',
    `total_expenditure_under_review_amt` DECIMAL(18,2) COMMENT 'Aggregate total expenditure in USD across all cost categories (CAPEX + OPEX + fuel) submitted for prudency review. This is the gross amount subject to the regulatory determination. Satisfies TRANSACTION_HEADER MONETARY_TRIPLET gross-base amount category.',
    `updated_timestamp` TIMESTAMP COMMENT 'Timestamp when this prudency review record was last modified in the data platform. Formatted as yyyy-MM-ddTHH:mm:ss.SSSXXX. Satisfies TRANSACTION_HEADER RECORD_AUDIT_UPDATED category.',
    `utility_witness_name` STRING COMMENT 'Name of the primary utility witness or subject matter expert who provided testimony or documentation in support of the prudency of the expenditures under review. Used for regulatory proceeding tracking and testimony management.',
    `wip_balance_amt` DECIMAL(18,2) COMMENT 'Dollar amount of Work in Progress (WIP) balance associated with the capital project under prudency review at the time of review initiation. Relevant for capital project prudency reviews to assess the in-service conversion and rate base eligibility.',
    CONSTRAINT pk_prudency_review PRIMARY KEY(`prudency_review_id`)
) COMMENT 'Master record for each prudency review or management audit initiated by a PUC or FERC to evaluate the reasonableness of utility expenditures for cost recovery. Captures review type (capital project prudency, O&M prudency, fuel cost prudency, storm cost recovery), triggering docket, review scope description, total expenditure under review (CAPEX/OPEX), reviewer identity (PUC staff, independent auditor), preliminary finding, final determination (prudent/imprudent/partial), disallowed amount, and effective date of determination.';

CREATE OR REPLACE TABLE `power_and_utilities`.`regulatory`.`cost_recovery_mechanism` (
    `cost_recovery_mechanism_id` BIGINT COMMENT 'Unique surrogate identifier for each approved regulatory cost recovery mechanism or rider record in the utilitys regulatory portfolio.',
    `cpcn_application_id` BIGINT COMMENT 'Foreign key linking to regulatory.cpcn_application. Business justification: Cost recovery mechanisms (CWIP, AFUDC, construction riders) are established for CPCN-approved projects. The cost_recovery_mechanism.cpcn_number STRING field should be normalized to a FK. This links co',
    `financial_period_id` BIGINT COMMENT 'Foreign key linking to finance.financial_period. Business justification: Cost recovery mechanisms (fuel adjustment clauses, storm cost recovery, DSM trackers) have true-up cycles tied to financial periods. Finance calculates quarterly/annual true-ups based on closed period',
    `docket_id` BIGINT COMMENT 'Reference to the regulatory docket record that authorized or governs this cost recovery mechanism. Links to the regulatory.docket product for full proceeding details.',
    `rate_case_id` BIGINT COMMENT 'Foreign key linking to regulatory.rate_case. Business justification: Cost recovery mechanisms are often established or modified through rate cases. While cost_recovery_mechanism already has docket_id, adding rate_case_id provides direct linkage to the rate case proceed',
    `afudc_rate_pct` DECIMAL(18,2) COMMENT 'The FERC-approved or PUC-approved AFUDC capitalization rate expressed as a percentage, applicable when mechanism_type is AFUDC. Represents the cost of capital applied to construction work in progress (WIP) balances. Null for non-AFUDC mechanism types.',
    `annual_cap_amount` DECIMAL(18,2) COMMENT 'Maximum dollar amount that may be recovered through this mechanism in a single calendar or regulatory year, as approved by the regulatory body. Null if no annual cap is imposed. Expressed in USD.',
    `approval_date` DATE COMMENT 'Date on which the regulatory body issued the final order or decision approving this cost recovery mechanism.',
    `approval_order_number` STRING COMMENT 'The official order, decision, or resolution number issued by the regulatory body that authorized this cost recovery mechanism. Used for audit trail and regulatory correspondence.',
    `balance_as_of_date` DATE COMMENT 'The date as of which the current_balance was last calculated or reported. Used to determine the staleness of the balance figure for reporting and true-up purposes.',
    `cost_recovery_mechanism_status` STRING COMMENT 'Current lifecycle status of the cost recovery mechanism: active = currently in effect and recovering costs; suspended = temporarily halted by regulatory order; terminated = permanently closed; pending_approval = filed but not yet approved; under_review = subject to ongoing prudency or audit review; expired = reached scheduled end date.. Valid values are `active|suspended|terminated|pending_approval|under_review|expired`',
    `current_balance` DECIMAL(18,2) COMMENT 'Current outstanding balance of costs accumulated in this cost recovery mechanism tracker as of the last true-up or reporting period. Positive balance indicates under-recovery (costs exceed collections); negative balance indicates over-recovery. Expressed in USD.',
    `current_rate_amount` DECIMAL(18,2) COMMENT 'The currently approved per-unit recovery rate applied to customer bills under this mechanism (e.g., cents per kWh for FAC, dollars per MCF for gas adjustment). The unit of measure is defined by recovery_method and service_type.',
    `customer_class_scope` STRING COMMENT 'The customer class or classes to which this cost recovery mechanism applies (e.g., Residential, Commercial, Industrial, All Classes). Determines which rate schedules include this mechanisms surcharge.',
    `disallowed_amount` DECIMAL(18,2) COMMENT 'Dollar amount of costs disallowed by the regulatory body following a prudency review or audit. Reduces the total recoverable amount. Expressed in USD. Zero if no disallowance has occurred.',
    `dsm_program_name` STRING COMMENT 'Name of the DSM or EE program whose costs are being recovered through this mechanism. Applicable when mechanism_type is DSM_EE_rider. Null for non-DSM mechanisms.',
    `effective_end_date` DATE COMMENT 'Date on which this cost recovery mechanism expires or is scheduled to terminate. Null for open-ended mechanisms with no defined sunset date.',
    `effective_start_date` DATE COMMENT 'Date on which this cost recovery mechanism becomes effective and the utility may begin recovering costs through rates. Typically aligned with the approved tariff effective date.',
    `ferc_account_number` STRING COMMENT 'The specific FERC Uniform System of Accounts account number applicable to this cost recovery mechanism (e.g., Account 182.3 for Other Regulatory Assets, Account 254 for Other Regulatory Liabilities). Required for FERC-jurisdictional utilities.',
    `filing_frequency` STRING COMMENT 'Frequency at which the utility must file reports, rate adjustment applications, or compliance filings with the regulatory body for this mechanism (e.g., monthly FAC filings, annual infrastructure rider updates).. Valid values are `monthly|quarterly|semi_annual|annual|as_needed`',
    `gl_account_code` STRING COMMENT 'The FERC Uniform System of Accounts or company general ledger account code to which costs accumulated under this mechanism are posted. Ensures proper regulatory accounting treatment and financial reporting alignment.',
    `interest_accrual_indicator` BOOLEAN COMMENT 'Indicates whether interest accrues on the outstanding balance of this cost recovery mechanism as approved by the regulatory body. True = interest accrues on under- or over-recovery balances; False = no interest accrual.',
    `interest_rate_pct` DECIMAL(18,2) COMMENT 'The approved interest rate percentage applied to the outstanding balance when interest_accrual_indicator is True. Typically set by the regulatory body in the approval order. Null when interest_accrual_indicator is False.',
    `jurisdiction` STRING COMMENT 'The regulatory jurisdiction governing this mechanism (e.g., state abbreviation for PUC-regulated mechanisms, FERC for federally regulated mechanisms). Determines which regulatory body must approve and oversee the mechanism.',
    `last_true_up_date` DATE COMMENT 'Date of the most recently completed true-up reconciliation for this mechanism. Used to track compliance with the approved true-up frequency and to identify overdue reconciliations.',
    `mechanism_code` STRING COMMENT 'Externally-known alphanumeric code assigned by the utility or regulatory body to uniquely identify this cost recovery mechanism or rider (e.g., FAC-001, AFUDC-2024, STORM-RIDER-TX). Used in tariff filings, rate schedules, and regulatory correspondence.. Valid values are `^[A-Z0-9_-]{2,30}$`',
    `mechanism_description` STRING COMMENT 'Detailed narrative description of the cost recovery mechanism, including its regulatory purpose, the types of costs it covers, and any special conditions or limitations imposed by the approving regulatory body.',
    `mechanism_name` STRING COMMENT 'Full descriptive name of the cost recovery mechanism as it appears in the approved tariff or regulatory order (e.g., Fuel Adjustment Clause, Infrastructure Modernization Rider, Storm Cost Recovery Tracker).',
    `mechanism_type` STRING COMMENT 'Classification of the cost recovery mechanism by regulatory category. FAC = Fuel Adjustment Clause; AFUDC = Allowance for Funds Used During Construction; CIAC = Contribution in Aid of Construction; infrastructure_rider = capital infrastructure surcharge; storm_cost_tracker = storm damage cost recovery; DSM_EE_rider = Demand-Side Management / Energy Efficiency program cost recovery. [ENUM-REF-CANDIDATE: FAC|AFUDC|CIAC|infrastructure_rider|storm_cost_tracker|DSM_EE_rider|other — promote to reference product]',
    `next_filing_due_date` DATE COMMENT 'Date by which the next required regulatory filing or rate adjustment application for this mechanism must be submitted to the regulatory body. Supports compliance calendar management.',
    `next_true_up_date` DATE COMMENT 'Scheduled date for the next true-up reconciliation filing with the regulatory body. Supports proactive compliance monitoring and workload planning.',
    `notes` STRING COMMENT 'Free-text field for regulatory staff to record supplemental information, open issues, pending actions, or contextual notes related to this cost recovery mechanism that are not captured in structured fields.',
    `prudency_review_required` BOOLEAN COMMENT 'Indicates whether costs recovered under this mechanism are subject to a regulatory prudency review before final recovery is confirmed. True = prudency review required; False = costs are pre-approved without individual prudency review.',
    `prudency_review_status` STRING COMMENT 'Current status of the prudency review for costs recovered under this mechanism: not_required = no review required; pending = review not yet initiated; in_progress = review underway; completed = review finalized; disallowed = costs partially or fully disallowed; approved = costs found prudent and approved for full recovery.. Valid values are `not_required|pending|in_progress|completed|disallowed|approved`',
    `rate_base_treatment` STRING COMMENT 'Regulatory accounting treatment of costs recovered under this mechanism with respect to the utilitys rate base: included = costs are part of the approved rate base; excluded = costs are recovered outside rate base as a rider; deferred = costs are deferred pending future rate case inclusion; amortized = costs are being amortized over an approved period.. Valid values are `included|excluded|deferred|amortized|other`',
    `rate_effective_date` DATE COMMENT 'Date on which the current_rate_amount became effective for billing purposes. Changes when a true-up or rate adjustment is approved.',
    `recovery_method` STRING COMMENT 'The billing methodology by which costs are recovered from customers: volumetric = per kWh or MCF consumed; fixed_charge = flat monthly charge per customer; percentage_of_bill = surcharge as a percentage of base bill; demand_charge = per kW of peak demand.. Valid values are `volumetric|fixed_charge|percentage_of_bill|demand_charge|other`',
    `recovery_period_months` STRING COMMENT 'Total approved recovery period in months over which the authorized costs are to be collected from customers. For amortized mechanisms, this defines the amortization schedule length.',
    `regulatory_asset_liability` STRING COMMENT 'Indicates whether this mechanism creates a regulatory asset (under-recovery, costs deferred for future collection), a regulatory liability (over-recovery, amounts owed back to customers), or neither (pass-through with no balance accumulation). Per GAAP ASC 980.. Valid values are `regulatory_asset|regulatory_liability|neither`',
    `regulatory_body` STRING COMMENT 'Name of the specific regulatory authority that approved and oversees this cost recovery mechanism (e.g., Texas PUC, California PUC, FERC, Illinois Commerce Commission).',
    `service_type` STRING COMMENT 'Utility service type to which this cost recovery mechanism applies: electric distribution, gas distribution, or combined electric and gas service.. Valid values are `electric|gas|combined|other`',
    `tariff_schedule_ref` STRING COMMENT 'Reference to the specific tariff schedule, rate schedule, or tariff sheet number in the utilitys filed tariff that implements this cost recovery mechanism. Used to cross-reference the regulatory authorization with the billing rate schedule.',
    `total_authorized_amount` DECIMAL(18,2) COMMENT 'Total dollar amount authorized by the regulatory body for recovery under this mechanism over its full approved life. Null for open-ended mechanisms without a defined total cap. Expressed in USD.',
    `true_up_frequency` STRING COMMENT 'Regulatory-approved frequency at which the cost recovery mechanism balance is reconciled and rates are adjusted to correct for over- or under-recovery (e.g., monthly for FAC, annual for infrastructure riders).. Valid values are `monthly|quarterly|semi_annual|annual|as_needed`',
    `wip_balance` DECIMAL(18,2) COMMENT 'Current construction Work in Progress balance associated with this AFUDC or infrastructure rider mechanism. Applicable when mechanism_type is AFUDC or infrastructure_rider. Expressed in USD. Null for non-capital mechanisms.',
    CONSTRAINT pk_cost_recovery_mechanism PRIMARY KEY(`cost_recovery_mechanism_id`)
) COMMENT 'Master record for each approved regulatory cost recovery mechanism or rider in effect for the utility. Covers FAC (Fuel Adjustment Clause), AFUDC (Allowance for Funds Used During Construction), CIAC (Contribution in Aid of Construction), infrastructure riders, storm cost recovery trackers, and DSM/EE program cost recovery mechanisms. Captures mechanism type, regulatory approval reference, recovery period, rate base treatment, annual cap (if any), current balance, and true-up frequency. Distinct from billing rate schedules — this is the regulatory authorization record.';

CREATE OR REPLACE TABLE `power_and_utilities`.`regulatory`.`commission_order` (
    `commission_order_id` BIGINT COMMENT 'Unique surrogate identifier for each commission order record in the regulatory data product. Primary key for the commission_order entity in the Databricks Silver Layer.',
    `docket_id` BIGINT COMMENT 'Reference to the regulatory docket or proceeding that gave rise to this commission order. Links the order back to the originating proceeding tracked in the docket product.',
    `financial_period_id` BIGINT COMMENT 'Foreign key linking to finance.financial_period. Business justification: Commission orders with financial impacts (rate changes, refunds, penalties, regulatory asset approvals) must be recorded in specific financial periods for GAAP compliance. Regulatory accounting posts ',
    `rate_case_id` BIGINT COMMENT 'Reference to the rate case record associated with this commission order, when the order results from a rate case proceeding. Nullable for orders not tied to a rate case (e.g., NERC penalty notices, EPA compliance orders).',
    `appeal_deadline_date` DATE COMMENT 'The date by which any party (utility, intervenors, or regulatory staff) must file an appeal, request for rehearing, or petition for review of the commission order. Calculated from order_date per the issuing authoritys procedural rules.',
    `appeal_filed` BOOLEAN COMMENT 'Indicates whether an appeal, request for rehearing, or petition for judicial review has been filed against this commission order. True when an appeal has been filed; False when no appeal has been filed within the appeal period.',
    `appeal_filed_date` DATE COMMENT 'The date on which an appeal, request for rehearing, or petition for judicial review was formally filed against this commission order. Null when no appeal has been filed.',
    `appeal_status` STRING COMMENT 'Current status of any appeal filed against this commission order: not_appealed (no appeal filed), pending (appeal filed and under review), upheld (appellate authority affirmed the order), reversed (appellate authority overturned the order), remanded (appellate authority returned the order for further proceedings), withdrawn (appealing party withdrew the appeal).. Valid values are `not_appealed|pending|upheld|reversed|remanded|withdrawn`',
    `approved_rate_base` DECIMAL(18,2) COMMENT 'The total rate base approved by the commission in this order, expressed in U.S. dollars. Represents the net investment in utility plant and working capital on which the utility is authorized to earn a return. Null for orders not involving rate base determinations.',
    `approved_rate_change_pct` DECIMAL(18,2) COMMENT 'The percentage change in base rates approved by the commission order relative to existing rates. Positive values indicate a rate increase; negative values indicate a rate decrease. Null for orders not involving base rate changes.',
    `approved_revenue_requirement` DECIMAL(18,2) COMMENT 'The total annual revenue requirement approved by the regulatory authority in this commission order, expressed in U.S. dollars. Represents the amount the utility is authorized to collect from ratepayers to recover its prudently incurred costs plus a reasonable return. Null for orders not involving revenue requirement determinations.',
    `approved_roe_pct` DECIMAL(18,2) COMMENT 'The allowed Return on Equity (ROE) percentage approved by the commission in this order. Represents the authorized rate of return on the equity component of the utilitys capital structure. Null for orders not involving ROE determinations.',
    `compliance_deadline_date` DATE COMMENT 'The date by which the utility must complete all compliance actions mandated by the commission order, such as filing compliance tariffs, implementing approved rates, submitting compliance reports, or completing required infrastructure changes.',
    `compliance_filing_date` DATE COMMENT 'The date on which the utility submitted its required compliance filing to the regulatory authority in response to this commission order. Null when no compliance filing has been submitted or is not required.',
    `compliance_filing_required` BOOLEAN COMMENT 'Indicates whether the commission order requires the utility to submit a compliance filing (e.g., compliance tariff, compliance report, or compliance plan) to the regulatory authority by the compliance_deadline_date. True when a compliance filing is mandated.',
    `confidential_flag` BOOLEAN COMMENT 'Indicates whether this commission order or any of its associated documents have been designated as confidential or protected from public disclosure by the issuing regulatory authority. True when the order or supporting materials are subject to a protective order or confidentiality designation.',
    `cpcn_project_name` STRING COMMENT 'Name of the capital project or infrastructure investment for which a Certificate of Public Convenience and Necessity (CPCN) is granted or denied by this commission order. Applicable only for CPCN proceedings. Null for all other order types.',
    `created_timestamp` TIMESTAMP COMMENT 'The timestamp when this commission order record was first created in the regulatory data product. Audit field capturing the initial data ingestion or manual entry event in the Databricks Silver Layer.',
    `customer_class_scope` STRING COMMENT 'The customer class or rate class to which the commission orders directives or approved rates apply. Values: residential, commercial, industrial, large_power, or all_classes when the order applies universally across all customer segments.. Valid values are `residential|commercial|industrial|all_classes|large_power`',
    `effective_date` DATE COMMENT 'The date on which the commission orders directives, approved rates, or compliance obligations become legally effective and binding on the utility. May differ from order_date when the order specifies a future effective date or when interim rates are superseded.',
    `fac_indicator` BOOLEAN COMMENT 'Indicates whether this commission order involves a Fuel Adjustment Clause (FAC) or fuel cost recovery mechanism. True when the order approves, modifies, or audits FAC rates or fuel cost pass-through provisions.',
    `ghg_program_ref` STRING COMMENT 'Reference identifier for the Greenhouse Gas (GHG) or emissions compliance program associated with this commission order (e.g., EPA Clean Air Act permit number, state GHG program ID, Renewable Portfolio Standard (RPS) compliance docket reference). Null for orders not related to GHG or emissions compliance.',
    `issuing_authority` STRING COMMENT 'The regulatory body that issued this commission order. Identifies the jurisdictional authority: Public Utility Commission (PUC), Federal Energy Regulatory Commission (FERC), North American Electric Reliability Corporation (NERC), U.S. Environmental Protection Agency (EPA), U.S. Department of Energy (DOE), or Pipeline and Hazardous Materials Safety Administration (PHMSA).. Valid values are `PUC|FERC|NERC|EPA|DOE|PHMSA`',
    `jurisdiction_state` STRING COMMENT 'Two-letter U.S. state abbreviation identifying the state jurisdiction for state PUC orders. Null for federal orders issued by FERC, NERC, or EPA. Used to segment regulatory obligations by state service territory.. Valid values are `^[A-Z]{2}$`',
    `lead_attorney` STRING COMMENT 'Name of the utilitys lead regulatory attorney or outside counsel responsible for managing the utilitys response to this commission order, including compliance filings, appeals, and regulatory correspondence.',
    `nerc_standard_ref` STRING COMMENT 'The specific North American Electric Reliability Corporation (NERC) reliability standard identifier (e.g., FAC-001, PRC-005, CIP-007) that is the subject of this commission order. Applicable for NERC compliance and enforcement orders. Null for non-NERC proceedings.',
    `order_date` DATE COMMENT 'The official date on which the regulatory authority issued and signed the commission order. This is the authoritative date of the regulatory decision and is used for compliance deadline calculations and appeal period tracking.',
    `order_number` STRING COMMENT 'Externally assigned alphanumeric identifier issued by the regulatory authority (PUC, FERC, NERC, or EPA) uniquely identifying this order within the issuing bodys docket system. Used for official correspondence and regulatory filings.',
    `order_status` STRING COMMENT 'Current lifecycle status of the commission order: issued (order is in effect), appealed (utility or intervenor has filed an appeal), stayed (order execution suspended pending appeal or court action), vacated (order overturned by appellate authority), superseded (replaced by a subsequent order), closed (all compliance obligations fulfilled and order administratively closed).. Valid values are `issued|appealed|stayed|vacated|superseded|closed`',
    `order_summary` STRING COMMENT 'Plain-language summary of the commission orders key findings, directives, and decisions. Captures the substance of the regulatory ruling including approved actions, denied requests, required compliance measures, and any conditions imposed on the utility.',
    `order_type` STRING COMMENT 'Classification of the commission order by its legal and procedural nature: final_order (definitive ruling concluding a proceeding), interim_order (temporary ruling pending final decision), consent_order (negotiated settlement order), show_cause_order (directive requiring the utility to demonstrate compliance or justification), penalty_notice (formal notice of civil penalty or fine). [ENUM-REF-CANDIDATE: final_order|interim_order|consent_order|show_cause_order|penalty_notice|declaratory_order|compliance_order — promote to reference product]. Valid values are `final_order|interim_order|consent_order|show_cause_order|penalty_notice`',
    `pbr_indicator` BOOLEAN COMMENT 'Indicates whether this commission order establishes, modifies, or evaluates a Performance-Based Ratemaking (PBR) mechanism. True when the order includes PBR provisions such as earnings sharing, efficiency incentives, or reliability performance metrics tied to rate adjustments.',
    `penalty_amount` DECIMAL(18,2) COMMENT 'The civil monetary penalty or fine assessed against the utility in this commission order, expressed in U.S. dollars. Applicable for penalty notices, show cause orders, and NERC/EPA enforcement actions. Null for orders that do not impose a financial penalty.',
    `priority_level` STRING COMMENT 'Internal priority classification assigned to this commission order based on its financial impact, compliance risk, and operational urgency: critical (immediate executive attention required, major financial or operational impact), high (significant compliance obligation with near-term deadline), medium (standard compliance obligation), low (routine or informational order with minimal operational impact).. Valid values are `critical|high|medium|low`',
    `proceeding_type` STRING COMMENT 'Category of the regulatory proceeding that produced this order: rate_case (general rate case), cpcn (Certificate of Public Convenience and Necessity), irp (Integrated Resource Plan), tariff_filing (tariff amendment or OATT filing), nerc_compliance (NERC reliability standard compliance), ghg_compliance (Greenhouse Gas/emissions compliance), oatt (Open Access Transmission Tariff), nem (Net Energy Metering), dr_program (Demand Response program approval). [ENUM-REF-CANDIDATE: rate_case|cpcn|irp|tariff_filing|nerc_compliance|ghg_compliance|oatt|nem|dr_program|pbr|other — promote to reference product]',
    `refund_amount` DECIMAL(18,2) COMMENT 'The total amount the utility is ordered to refund to customers as directed by this commission order, expressed in U.S. dollars. Applicable when the commission determines the utility over-collected revenues or charged rates in excess of approved levels. Null when no refund is ordered.',
    `refund_deadline_date` DATE COMMENT 'The date by which the utility must complete the distribution of ordered customer refunds. Null when no refund is required by this order.',
    `regulatory_case_manager` STRING COMMENT 'Name of the internal regulatory affairs staff member or case manager responsible for tracking compliance obligations, coordinating cross-functional responses, and maintaining the utilitys records for this commission order.',
    `service_type` STRING COMMENT 'The regulated utility service type to which this commission order applies: electric (electric distribution), gas (natural gas distribution), electric_and_gas (combined electric and gas), transmission (high-voltage electric transmission), generation (electric generation). Determines which operational domain is subject to the orders directives.. Valid values are `electric|gas|electric_and_gas|transmission|generation`',
    `stay_expiration_date` DATE COMMENT 'The date on which a stay of the commission order expires or is lifted, after which the orders directives become effective. Null when no stay has been issued.',
    `stay_issued` BOOLEAN COMMENT 'Indicates whether a stay of the commission order has been granted by the issuing authority or an appellate court, suspending the orders effectiveness pending resolution of an appeal or rehearing. True when a stay is in effect.',
    `tariff_schedule_ref` STRING COMMENT 'Reference to the specific tariff schedule, rate schedule, or Open Access Transmission Tariff (OATT) section that is approved, modified, or superseded by this commission order. Used to link the order to the utilitys filed tariff documents.',
    `updated_timestamp` TIMESTAMP COMMENT 'The timestamp when this commission order record was most recently modified in the regulatory data product. Audit field tracking the last update to any attribute, used for change detection and incremental processing in the Databricks Silver Layer.',
    CONSTRAINT pk_commission_order PRIMARY KEY(`commission_order_id`)
) COMMENT 'Transactional record of each final order, decision, or ruling issued by a regulatory authority (PUC, FERC, NERC, EPA) in connection with a docket or proceeding. Captures order number, issuing authority, order date, order type (final order, interim order, consent order, show cause order, penalty notice), summary of decision, approved revenue requirement or rate change, compliance deadline, appeal period, and appeal status. Serves as the authoritative record of regulatory decisions binding on the utility.';

CREATE OR REPLACE TABLE `power_and_utilities`.`regulatory`.`rider_charge` (
    `rider_charge_id` BIGINT COMMENT 'Unique identifier for the regulatory rider or surcharge record. Primary key for the rider_charge product.',
    `cost_recovery_mechanism_id` BIGINT COMMENT 'Foreign key linking to regulatory.cost_recovery_mechanism. Business justification: Rider charges are the customer-facing implementation of cost recovery mechanisms. Each rider_charge should reference the underlying cost_recovery_mechanism that defines the regulatory authorization an',
    `docket_id` BIGINT COMMENT 'Foreign key linking to regulatory.docket. Business justification: Rider charges are approved under regulatory dockets. The rider_charge table currently has docket_number as STRING; this should be normalized to a FK relationship. Remove docket_number STRING and repla',
    `superseded_by_rider_rider_charge_id` BIGINT COMMENT 'Foreign key reference to the rider_charge_id that supersedes this rider. Null if this rider is current or was not replaced by another rider.',
    `afudc_rate_pct` DECIMAL(18,2) COMMENT 'AFUDC rate percentage applied to deferred balances or work-in-progress costs recovered through this rider. Null if AFUDC does not apply.',
    `annual_cap_amount` DECIMAL(18,2) COMMENT 'Maximum annual revenue that may be collected through this rider, if a regulatory cap is imposed. Null for uncapped riders.',
    `approval_date` DATE COMMENT 'Date on which the regulatory authority (PUC or FERC) approved this rider charge through a commission order.',
    `approval_order_number` STRING COMMENT 'Commission order number or docket decision reference that authorized this rider charge. Links to the regulatory approval record.',
    `balance_as_of_date` DATE COMMENT 'Date as of which the current_balance was calculated. Updated with each true-up filing or monthly reconciliation.',
    `charge_basis` STRING COMMENT 'Unit of measure or calculation method for applying the rider charge: per kilowatt-hour (kWh), per thousand cubic feet (MCF) of gas, per therm, per kilowatt (kW) of demand, fixed monthly amount, or percentage of base tariff charges.. Valid values are `per_kwh|per_mcf|per_therm|per_kw|fixed_monthly|percentage_of_base`',
    `created_timestamp` TIMESTAMP COMMENT 'Timestamp when this rider charge record was first created in the system. Used for audit trail and data lineage.',
    `currency_code` STRING COMMENT 'Three-letter ISO 4217 currency code for the rate value (typically USD for U.S. utilities).. Valid values are `^[A-Z]{3}$`',
    `current_balance` DECIMAL(18,2) COMMENT 'Current outstanding balance of costs to be recovered or refunded through this rider. Positive values indicate under-recovery; negative values indicate over-recovery requiring refund.',
    `current_rate_value` DECIMAL(18,2) COMMENT 'The currently effective rate value for this rider charge, expressed in the unit specified by charge_basis (e.g., 0.012345 dollars per kWh, 2.50 dollars per month). Updated through regulatory true-up filings.',
    `customer_class_scope` STRING COMMENT 'Comma-separated list of customer classes to which this rider applies (e.g., residential, commercial, industrial, street_lighting). Determines billing applicability by rate schedule.',
    `effective_date` DATE COMMENT 'Date on which this rider charge becomes effective and begins to be applied to customer bills. Corresponds to the regulatory approval order effective date.',
    `expiration_date` DATE COMMENT 'Date on which this rider charge expires or is scheduled to be superseded. Null for riders with indefinite duration subject to periodic true-up.',
    `ferc_account_number` STRING COMMENT 'FERC Uniform System of Accounts number for the regulatory asset, liability, or revenue account associated with this rider (e.g., Account 182.3 for regulatory assets).',
    `filing_date` DATE COMMENT 'Date on which the utility filed the tariff rider application or true-up filing with the regulatory authority.',
    `gl_account_code` STRING COMMENT 'General ledger account code in the utilitys chart of accounts to which rider revenues and costs are posted.',
    `interest_accrual_indicator` BOOLEAN COMMENT 'Indicates whether interest accrues on the deferred balance of this rider. True if interest is calculated on under-recovered or over-recovered amounts.',
    `interest_rate_pct` DECIMAL(18,2) COMMENT 'Annual interest rate percentage applied to deferred balances, if interest accrual is enabled. Typically based on the utilitys weighted average cost of capital (WACC) or a regulatory-specified rate.',
    `jurisdiction` STRING COMMENT 'Level of regulatory jurisdiction governing this rider: federal (FERC), state (PUC), or municipal.. Valid values are `federal|state|municipal`',
    `jurisdiction_state_code` STRING COMMENT 'Two-letter U.S. state code for the state regulatory jurisdiction (e.g., CA, NY, TX). Null for federal or multi-state riders.. Valid values are `^[A-Z]{2}$`',
    `last_true_up_date` DATE COMMENT 'Date of the most recent true-up filing or rate adjustment for this rider. Used to track compliance with regulatory true-up schedules.',
    `next_true_up_date` DATE COMMENT 'Scheduled date for the next true-up filing or rate adjustment. Null for riders without periodic true-up requirements.',
    `rate_base_treatment` STRING COMMENT 'Indicates whether costs recovered through this rider are included in rate base, excluded from rate base, or deferred as a regulatory asset/liability.. Valid values are `included|excluded|deferred`',
    `recovery_method` STRING COMMENT 'Method by which costs are recovered: current recovery (costs collected as incurred), deferred recovery (costs accumulated and recovered over time), or refund (over-collected amounts returned to customers).. Valid values are `current_recovery|deferred_recovery|refund`',
    `regulatory_asset_liability` STRING COMMENT 'Indicates whether this rider creates a regulatory asset (under-recovery), regulatory liability (over-recovery), or neither (current recovery with no deferral).. Valid values are `asset|liability|none`',
    `regulatory_body` STRING COMMENT 'Name of the regulatory authority that approved this rider (e.g., California Public Utilities Commission, Federal Energy Regulatory Commission).',
    `rider_charge_status` STRING COMMENT 'Current lifecycle status of the rider charge. Active riders are applied to customer bills; pending riders await regulatory approval; expired riders are no longer in effect.. Valid values are `active|pending_approval|suspended|expired|superseded`',
    `rider_code` STRING COMMENT 'Short alphanumeric code uniquely identifying the rider or surcharge within the utilitys tariff structure (e.g., FAC, RPS, INFRA, DSM). Used as the business identifier for rate engine processing.. Valid values are `^[A-Z0-9_-]{2,20}$`',
    `rider_description` STRING COMMENT 'Detailed description of the riders purpose, cost recovery mechanism, and regulatory basis. Includes information on the types of costs recovered and the calculation methodology.',
    `rider_name` STRING COMMENT 'Full descriptive name of the rider or surcharge as it appears on customer bills and in regulatory filings (e.g., Fuel Adjustment Clause, Renewable Portfolio Standard Surcharge, Infrastructure Investment Rider).',
    `rider_type` STRING COMMENT 'Classification of the rider based on its regulatory purpose and cost recovery mechanism. Determines the accounting treatment and regulatory reporting requirements. [ENUM-REF-CANDIDATE: fuel_adjustment|renewable_portfolio|infrastructure_investment|low_income_program|demand_response|environmental_compliance|ciac_recovery|energy_efficiency|other — 9 candidates stripped; promote to reference product]',
    `service_type` STRING COMMENT 'Type of utility service to which this rider applies: electric, natural gas, or dual fuel (both electric and gas).. Valid values are `electric|gas|dual_fuel`',
    `tariff_schedule_ref` STRING COMMENT 'Reference to the base tariff schedule(s) to which this rider applies. May be a single schedule number or a comma-separated list for riders applicable across multiple schedules.',
    `total_authorized_amount` DECIMAL(18,2) COMMENT 'Total cumulative amount authorized for recovery through this rider over its lifetime (e.g., total project cost for a CIAC recovery rider). Null for ongoing riders without a fixed total.',
    `true_up_frequency` STRING COMMENT 'Frequency at which the rider rate is recalculated and adjusted based on actual costs versus forecasted costs (e.g., monthly for FAC, annual for infrastructure riders).. Valid values are `monthly|quarterly|semi_annual|annual|none`',
    `updated_timestamp` TIMESTAMP COMMENT 'Timestamp when this rider charge record was last modified. Updated with each true-up filing, rate change, or status update.',
    CONSTRAINT pk_rider_charge PRIMARY KEY(`rider_charge_id`)
) COMMENT 'Regulatory rider and surcharge master defining all PUC-approved cost-recovery mechanisms applied to customer bills as separate line items beyond base tariff rates — Fuel Adjustment Clause (FAC), Renewable Portfolio Standard (RPS) surcharge, CIAC recovery rider, infrastructure investment rider, low-income program rider, demand response program charge, and environmental compliance surcharge. Captures rider code, rider name, regulatory approval order reference, applicable customer classes, charge basis (per kWh, per MCF, per Therm, per kW, fixed monthly), effective date, expiration date, and current rate value. Each rider has its own regulatory approval lifecycle independent of base rate schedule changes. Sourced from PUC-approved tariff riders and maintained in Oracle CC&B / SAP IS-U rate engine. SSOT for all regulatory surcharges — distinct from rate_schedule, which owns base tariff rate definitions.';

CREATE OR REPLACE TABLE `power_and_utilities`.`regulatory`.`compliance_calendar` (
    `compliance_calendar_id` BIGINT COMMENT 'Unique identifier for each regulatory deadline, milestone, or scheduled compliance event tracked by the utility. Primary key for the compliance calendar registry.',
    `compliance_obligation_id` BIGINT COMMENT 'Reference to the compliance obligation record that drives this deadline, if the deadline is compliance-driven (e.g., NERC audit window, EPA reporting deadline, PHMSA inspection window).',
    `docket_id` BIGINT COMMENT 'Reference to the regulatory docket or proceeding associated with this deadline, if the deadline is proceeding-related (e.g., rate case milestone, CPCN application deadline, IRP submission due date).',
    `filing_id` BIGINT COMMENT 'Foreign key linking to regulatory.filing. Business justification: Compliance calendar events track specific filing deadlines (e.g., File quarterly NERC compliance report by 2024-04-15). Each calendar event can reference the specific filing record it tracks. This c',
    `employee_id` BIGINT COMMENT 'Employee identifier for the individual assigned primary accountability for this compliance deadline. Links to the workforce or human capital management system.',
    `parent_compliance_calendar_id` BIGINT COMMENT 'Self-referencing FK on compliance_calendar (parent_compliance_calendar_id)',
    `alert_status` STRING COMMENT 'Current state of the alert mechanism for this deadline. Indicates whether an alert has been triggered, escalated to management, or acknowledged by the responsible party.. Valid values are `no_alert|alert_triggered|escalated|acknowledged`',
    `alert_threshold_days` STRING COMMENT 'The number of days before the effective due date at which an alert or notification should be triggered to the responsible party and escalation contact. Configurable per deadline type and risk level.',
    `completion_date` DATE COMMENT 'The actual date on which the filing, submission, or compliance action was completed and submitted to the regulatory body. Null if the deadline has not yet been met.',
    `completion_status` STRING COMMENT 'Current status of the compliance deadline indicating whether the obligation has been met, is in progress, or has been missed. Drives operational workflow and escalation logic. [ENUM-REF-CANDIDATE: pending|in_progress|completed_on_time|completed_late|missed|waived|cancelled — 7 candidates stripped; promote to reference product]',
    `compliance_domain` STRING COMMENT 'The functional domain or category of compliance to which this deadline belongs (e.g., reliability standards, environmental reporting, safety inspections, financial filings, cybersecurity audits, rate regulation). Enables domain-specific reporting and resource planning. [ENUM-REF-CANDIDATE: reliability|environmental|safety|financial|operational|cybersecurity|rate_regulation|other — 8 candidates stripped; promote to reference product]',
    `confirmation_number` STRING COMMENT 'The confirmation or tracking number provided by the regulatory body upon successful submission of the filing or compliance evidence. Serves as proof of timely submission.',
    `created_timestamp` TIMESTAMP COMMENT 'The date and time when this compliance calendar record was first created in the system. Supports audit trail and data lineage tracking.',
    `days_to_deadline` STRING COMMENT 'Calculated number of calendar days remaining until the effective due date. Negative values indicate the deadline has passed. Used to trigger alerts and prioritize work queues.',
    `deadline_type` STRING COMMENT 'Classification of the type of regulatory deadline or milestone being tracked. Determines the nature of the obligation and the required action by the utility. [ENUM-REF-CANDIDATE: filing_due_date|compliance_evidence_submission|rate_case_milestone|irp_update_cycle|annual_report_due_date|audit_window|inspection_window|testimony_deadline|tariff_filing_deadline|other — 10 candidates stripped; promote to reference product]',
    `effective_due_date` DATE COMMENT 'The current operative deadline date that the utility must meet. Equals extended_due_date if an extension was granted, otherwise equals original_due_date. This is the date used for alert calculations and compliance tracking.',
    `escalation_contact` STRING COMMENT 'Name or identifier of the escalation contact or manager to be notified if the deadline is at risk of being missed or if issues arise during compliance preparation.',
    `event_name` STRING COMMENT 'Descriptive name or title of the compliance deadline or milestone (e.g., Q1 FERC Form 1 Filing, Annual NERC CIP Audit, Rate Case Testimony Submission, IRP Update Cycle 2024).',
    `event_notes` STRING COMMENT 'Free-text field for additional context, instructions, special conditions, or internal notes related to this compliance deadline. Captures information not covered by structured fields.',
    `event_number` STRING COMMENT 'Business-assigned unique identifier or tracking number for this compliance calendar event, used for internal reference and communication across regulatory affairs teams.',
    `extended_due_date` DATE COMMENT 'The revised deadline date if an extension has been granted by the regulatory body. Null if no extension has been requested or approved. This becomes the operative deadline when populated.',
    `extension_approval_date` DATE COMMENT 'The date on which the regulatory body formally approved the extension request. Null if no extension was granted.',
    `extension_granted_indicator` BOOLEAN COMMENT 'Flag indicating whether the regulatory body has approved the extension request. True if the extension was granted and extended_due_date has been populated.',
    `extension_request_date` DATE COMMENT 'The date on which the utility submitted a formal request for deadline extension to the regulatory body. Null if no extension has been requested.',
    `extension_requested_indicator` BOOLEAN COMMENT 'Flag indicating whether the utility has formally requested an extension of the original deadline from the regulatory body. True if an extension request has been submitted.',
    `jurisdiction` STRING COMMENT 'The regulatory jurisdiction or geographic scope to which this deadline applies (e.g., federal, state-specific, multi-state, RTO/ISO region). Identifies the legal and geographic boundaries of the compliance obligation.',
    `jurisdiction_state` STRING COMMENT 'Two-letter state code identifying the specific state jurisdiction for state-level regulatory deadlines (e.g., CA for California PUC, NY for New York PSC). Null for federal or multi-state deadlines.',
    `next_occurrence_date` DATE COMMENT 'For recurring deadlines, the date of the next scheduled occurrence after the current effective due date. Used for forward planning and resource allocation.',
    `original_due_date` DATE COMMENT 'The initial statutory or regulatory deadline date as established by the governing body or regulatory order. This date does not change even if extensions are granted.',
    `penalty_exposure_amount` DECIMAL(18,2) COMMENT 'Estimated financial penalty or fine exposure (in USD) if this deadline is missed or the compliance obligation is not met. Used for risk assessment and prioritization. Null if no specific penalty is defined.',
    `priority_level` STRING COMMENT 'Business-assigned priority classification for this compliance deadline based on regulatory impact, penalty exposure, and strategic importance. Drives resource allocation and management attention.. Valid values are `critical|high|medium|low`',
    `recurrence_frequency` STRING COMMENT 'The frequency at which this compliance deadline recurs, if recurrence_indicator is true. Defines the cadence for automatic generation of future deadline instances. [ENUM-REF-CANDIDATE: daily|weekly|monthly|quarterly|semi_annual|annual|biennial|ad_hoc — 8 candidates stripped; promote to reference product]',
    `recurrence_indicator` BOOLEAN COMMENT 'Flag indicating whether this is a recurring compliance deadline (e.g., quarterly FERC filings, annual NERC audits) or a one-time event (e.g., specific rate case milestone, CPCN application deadline). True for recurring events.',
    `regulatory_body` STRING COMMENT 'The regulatory authority or governing body to which this deadline applies (e.g., Federal Energy Regulatory Commission (FERC), North American Electric Reliability Corporation (NERC), State Public Utility Commission (PUC), Environmental Protection Agency (EPA), Pipeline and Hazardous Materials Safety Administration (PHMSA)). [ENUM-REF-CANDIDATE: FERC|NERC|PUC|EPA|DOE|PHMSA|OSHA|state_commission|other — 9 candidates stripped; promote to reference product]',
    `regulatory_standard_ref` STRING COMMENT 'Citation or reference to the specific regulatory standard, rule, or statute that establishes this deadline (e.g., NERC CIP-007-6, EPA 40 CFR Part 75, FERC Order 1000, state tariff section). Provides legal traceability.',
    `responsible_party` STRING COMMENT 'Name or identifier of the internal business unit, department, or individual responsible for ensuring this deadline is met (e.g., Regulatory Affairs, Compliance Manager, Rate Case Team, Environmental Compliance Officer).',
    `service_type` STRING COMMENT 'The type of utility service to which this compliance deadline applies (electric generation/transmission/distribution, natural gas distribution, combined services). Enables service-specific compliance tracking.. Valid values are `electric|gas|steam|water|combined`',
    `submission_method` STRING COMMENT 'The method or channel by which the compliance filing or evidence must be submitted to the regulatory body (e.g., electronic filing portal, email, physical mail, hand delivery).. Valid values are `electronic_portal|email|physical_mail|hand_delivery|fax|other`',
    `updated_timestamp` TIMESTAMP COMMENT 'The date and time when this compliance calendar record was last modified. Supports change tracking and audit trail requirements.',
    CONSTRAINT pk_compliance_calendar PRIMARY KEY(`compliance_calendar_id`)
) COMMENT 'Master record for each regulatory deadline, milestone, or scheduled event the utility must track across all jurisdictions and regulatory bodies. Captures deadline type (filing due date, compliance evidence submission, rate case milestone, IRP update cycle, annual report due date, NERC audit window, EPA reporting deadline, PHMSA inspection window), associated docket or compliance obligation reference, jurisdiction, regulatory body, responsible internal party, original due date, extended due date (if granted), completion status, days-to-deadline alert threshold, and escalation contact. Links to docket for proceeding-related deadlines and to compliance_obligation for compliance-driven deadlines. Serves as the centralized deadline management registry that regulatory affairs teams use daily to ensure no filing or compliance deadline is missed — the operational heartbeat of the regulatory department.';

CREATE OR REPLACE TABLE `power_and_utilities`.`regulatory`.`irp_portfolio` (
    `irp_portfolio_id` BIGINT COMMENT 'Primary key for irp_portfolio',
    `irp_submission_id` BIGINT COMMENT 'Foreign key linking to regulatory.irp_submission. Business justification: IRP portfolios represent alternative resource scenarios analyzed within a specific IRP submission. Each portfolio (preferred plan, alternative scenarios) belongs to one IRP submission filing. This est',
    `baseline_irp_portfolio_id` BIGINT COMMENT 'Self-referencing FK on irp_portfolio (baseline_irp_portfolio_id)',
    `approval_date` DATE COMMENT 'The date on which the regulatory commission approved this IRP portfolio, authorizing the utility to proceed with resource acquisition and cost recovery.',
    `carbon_constraint_scenario` STRING COMMENT 'The greenhouse gas emissions reduction policy or target applied to this portfolio scenario, reflecting regulatory mandates or voluntary commitments.',
    `carbon_reduction_target_percent` DECIMAL(18,2) COMMENT 'The percentage reduction in carbon dioxide equivalent emissions targeted by this portfolio relative to a baseline year, if applicable.',
    `created_timestamp` TIMESTAMP COMMENT 'The date and time when this IRP portfolio record was first created in the system.',
    `demand_side_management_mw` DECIMAL(18,2) COMMENT 'The total peak demand reduction in megawatts achieved through energy efficiency and demand response programs included in this portfolio.',
    `irp_portfolio_description` STRING COMMENT 'Detailed narrative description of the portfolio scenario, including key assumptions, strategic objectives, resource mix rationale, and alignment with regulatory requirements.',
    `energy_forecast_gwh` DECIMAL(18,2) COMMENT 'The total forecasted annual energy requirement in gigawatt-hours at the end of the planning horizon for this portfolio scenario.',
    `environmental_compliance_flag` BOOLEAN COMMENT 'Indicates whether this portfolio meets all applicable federal and state environmental regulations including EPA emissions standards and state climate mandates.',
    `filing_date` DATE COMMENT 'The date on which this IRP portfolio was officially filed with the Public Utilities Commission or other regulatory authority.',
    `filing_year` STRING COMMENT 'The calendar year in which this IRP portfolio was filed with the regulatory commission.',
    `jurisdiction` STRING COMMENT 'The state or federal jurisdiction under which this IRP portfolio was filed, represented by standard postal abbreviation (e.g., CA, TX, FERC).',
    `levelized_cost_per_mwh` DECIMAL(18,2) COMMENT 'The levelized cost of energy for this portfolio expressed in dollars per megawatt-hour, representing the average cost to generate and deliver electricity over the planning horizon.',
    `load_forecast_scenario` STRING COMMENT 'The demand growth assumption applied in this portfolio scenario, reflecting expected customer load patterns over the planning horizon.',
    `modeling_tool` STRING COMMENT 'The name of the capacity expansion or production cost modeling software used to develop and optimize this portfolio scenario (e.g., PLEXOS, Aurora, PROMOD).',
    `modified_timestamp` TIMESTAMP COMMENT 'The date and time when this IRP portfolio record was last modified in the system.',
    `peak_demand_mw` DECIMAL(18,2) COMMENT 'The forecasted system peak demand in megawatts at the end of the planning horizon for this portfolio scenario.',
    `planning_horizon_end_date` DATE COMMENT 'The last date of the planning period covered by this IRP portfolio scenario, typically 10-20 years from the start date depending on regulatory requirements.',
    `planning_horizon_start_date` DATE COMMENT 'The first date of the planning period covered by this IRP portfolio scenario, typically the beginning of the first forecast year.',
    `portfolio_code` STRING COMMENT 'Short alphanumeric code used to reference this portfolio in regulatory filings, internal planning documents, and cross-system references.',
    `portfolio_name` STRING COMMENT 'Business name or label assigned to this IRP portfolio scenario for identification and reporting purposes.',
    `portfolio_type` STRING COMMENT 'Classification of the portfolio scenario based on planning assumptions and strategic objectives. Base case represents the most likely scenario; preferred represents the utilitys recommended resource plan.',
    `reliability_score` DECIMAL(18,2) COMMENT 'A quantitative reliability assessment score for this portfolio based on resource adequacy, transmission constraints, and operational flexibility metrics.',
    `renewable_capacity_mw` DECIMAL(18,2) COMMENT 'The total installed renewable generation capacity in megawatts (solar, wind, hydro, biomass) included in this portfolio at the end of the planning horizon.',
    `renewable_portfolio_standard_percent` DECIMAL(18,2) COMMENT 'The target percentage of energy generation from renewable sources required by state RPS mandates or voluntary commitments in this portfolio.',
    `reserve_margin_percent` DECIMAL(18,2) COMMENT 'The target planning reserve margin expressed as a percentage of peak demand, ensuring adequate capacity to meet reliability standards.',
    `risk_score` DECIMAL(18,2) COMMENT 'A quantitative risk assessment score for this portfolio based on sensitivity analysis of fuel price volatility, load uncertainty, regulatory changes, and technology performance.',
    `sensitivity_analysis_performed` BOOLEAN COMMENT 'Indicates whether sensitivity analysis was performed on this portfolio to test robustness against variations in key assumptions such as fuel prices, load growth, and technology costs.',
    `stakeholder_input_summary` STRING COMMENT 'A summary of key stakeholder feedback received during the IRP public comment process, including input from consumer advocates, environmental groups, and industry participants.',
    `irp_portfolio_status` STRING COMMENT 'Current lifecycle status of the IRP portfolio within the planning and regulatory approval process.',
    `storage_capacity_mw` DECIMAL(18,2) COMMENT 'The total installed energy storage capacity in megawatts (battery, pumped hydro, etc.) included in this portfolio at the end of the planning horizon.',
    `total_capacity_mw` DECIMAL(18,2) COMMENT 'The total installed generation capacity in megawatts included in this portfolio at the end of the planning horizon.',
    `total_portfolio_cost_million` DECIMAL(18,2) COMMENT 'The total net present value cost of this portfolio in millions of dollars over the planning horizon, including capital, operating, fuel, and environmental compliance costs.',
    CONSTRAINT pk_irp_portfolio PRIMARY KEY(`irp_portfolio_id`)
) COMMENT 'Master reference table for irp_portfolio. Referenced by irp_portfolio_id.';

CREATE OR REPLACE TABLE `power_and_utilities`.`regulatory`.`rps_program` (
    `rps_program_id` BIGINT COMMENT 'Primary key for rps_program',
    `commission_order_id` BIGINT COMMENT 'Foreign key linking to regulatory.commission_order. Business justification: RPS programs are approved and modified via commission orders (e.g., Order 2024-123: Approval of RPS Compliance Plan). The rps_program.order_number STRING field should be normalized to a FK. This lin',
    `docket_id` BIGINT COMMENT 'Foreign key linking to regulatory.docket. Business justification: RPS programs are established via regulatory dockets (e.g., Docket 2023-RPS-001: Renewable Portfolio Standard Rulemaking). The rps_program.docket_number STRING field should be normalized to a FK. Thi',
    `successor_rps_program_id` BIGINT COMMENT 'Self-referencing FK on rps_program (successor_rps_program_id)',
    `alternative_compliance_payment_rate` DECIMAL(18,2) COMMENT 'Dollar amount per megawatt-hour that utilities must pay as an alternative compliance payment if they fail to meet RPS targets.',
    `banking_allowed` BOOLEAN COMMENT 'Indicates whether excess renewable energy credits can be banked and carried forward to future compliance periods.',
    `banking_limit_years` STRING COMMENT 'Maximum number of years that banked renewable energy credits can be carried forward for compliance use.',
    `carve_out_solar_percentage` DECIMAL(18,2) COMMENT 'Specific percentage of the RPS target that must be met through solar energy resources, if mandated by the program.',
    `carve_out_wind_percentage` DECIMAL(18,2) COMMENT 'Specific percentage of the RPS target that must be met through wind energy resources, if mandated by the program.',
    `compliance_year` STRING COMMENT 'Calendar year for which the RPS program compliance obligations and targets apply.',
    `cost_cap_amount` DECIMAL(18,2) COMMENT 'Maximum dollar amount or percentage of retail rates that can be allocated to RPS program costs, if a cost cap is mandated.',
    `cost_recovery_mechanism` STRING COMMENT 'Method by which the utility recovers RPS program costs from customers through rates.',
    `created_timestamp` TIMESTAMP COMMENT 'Timestamp when this RPS program record was first created in the system.',
    `effective_date` DATE COMMENT 'Date on which the RPS program became effective and compliance obligations commenced.',
    `eligible_resource_types` STRING COMMENT 'Comma-separated list of renewable energy resource types that qualify for RPS compliance credit under this program (e.g., solar, wind, hydro, biomass, geothermal).',
    `enabling_legislation` STRING COMMENT 'Citation of the statute, law, or legislative act that established the RPS program mandate.',
    `expiration_date` DATE COMMENT 'Date on which the RPS program mandate expires or sunsets, if applicable. Null for programs with no defined end date.',
    `ghg_reduction_target_percentage` DECIMAL(18,2) COMMENT 'Associated greenhouse gas emissions reduction target percentage linked to the RPS program, if mandated.',
    `jurisdiction` STRING COMMENT 'State or federal jurisdiction under which the RPS program is regulated and administered.',
    `last_modified_date` DATE COMMENT 'Date when the RPS program terms, targets, or regulatory requirements were last amended or updated.',
    `penalty_rate` DECIMAL(18,2) COMMENT 'Dollar amount per megawatt-hour assessed as a penalty for non-compliance with RPS program requirements.',
    `program_code` STRING COMMENT 'Externally-known unique code or identifier for the RPS program as registered with the regulatory authority.',
    `program_description` STRING COMMENT 'Detailed narrative description of the RPS program objectives, structure, and key compliance requirements.',
    `program_name` STRING COMMENT 'Official name of the renewable portfolio standard program as filed with the regulatory commission.',
    `program_status` STRING COMMENT 'Current lifecycle status of the RPS program indicating its operational state and regulatory standing.',
    `program_type` STRING COMMENT 'Classification of the RPS program based on regulatory mandate and structure.',
    `rec_trading_allowed` BOOLEAN COMMENT 'Indicates whether the program permits trading or purchasing of renewable energy certificates to meet compliance obligations.',
    `regulatory_authority` STRING COMMENT 'Name of the regulatory body or commission that oversees and enforces the RPS program requirements.',
    `reporting_deadline_date` DATE COMMENT 'Annual deadline date by which RPS compliance reports must be filed with the regulatory authority.',
    `reporting_frequency` STRING COMMENT 'Frequency at which the utility must submit RPS compliance reports to the regulatory authority.',
    `target_mwh` DECIMAL(18,2) COMMENT 'Absolute renewable energy procurement target expressed in megawatt-hours for the compliance period.',
    `target_percentage` DECIMAL(18,2) COMMENT 'Mandated percentage of total retail electricity sales that must be sourced from renewable energy resources under this RPS program.',
    `updated_timestamp` TIMESTAMP COMMENT 'Timestamp when this RPS program record was last updated in the system.',
    CONSTRAINT pk_rps_program PRIMARY KEY(`rps_program_id`)
) COMMENT 'Master reference table for rps_program. Referenced by rps_program_id.';

CREATE OR REPLACE TABLE `power_and_utilities`.`regulatory`.`corrective_action_plan` (
    `corrective_action_plan_id` BIGINT COMMENT 'Primary key for corrective_action_plan',
    `compliance_obligation_id` BIGINT COMMENT 'Foreign key linking to regulatory.compliance_obligation. Business justification: Corrective action plans are created to remediate violations of specific compliance obligations (NERC standard violations, RPS shortfalls, emissions exceedances). This FK links the CAP to the obligatio',
    `docket_id` BIGINT COMMENT 'Reference to the regulatory docket or proceeding under which this corrective action plan was filed or required.',
    `violation_id` BIGINT COMMENT 'Reference to the underlying violation, non-compliance finding, or audit exception that triggered this corrective action plan.',
    `parent_corrective_action_plan_id` BIGINT COMMENT 'Self-referencing FK on corrective_action_plan (parent_corrective_action_plan_id)',
    `actual_completion_date` DATE COMMENT 'Actual date on which all corrective actions were completed and verified, marking closure of the plan.',
    `actual_cost_amount` DECIMAL(18,2) COMMENT 'Actual total cost in USD incurred to implement the corrective action plan, tracked upon completion.',
    `approval_date` DATE COMMENT 'Date on which the corrective action plan was approved by the regulatory authority or internal governance body, authorizing implementation.',
    `closure_notes` STRING COMMENT 'Final notes or comments documenting the closure of the corrective action plan, including any lessons learned or follow-up actions required.',
    `cost_recovery_mechanism` STRING COMMENT 'The regulatory mechanism or tariff rider through which costs associated with the corrective action plan may be recovered from ratepayers (e.g., Fuel Adjustment Clause (FAC), Allowance for Funds Used During Construction (AFUDC), deferred accounting).',
    `created_timestamp` TIMESTAMP COMMENT 'Timestamp when this corrective action plan record was first created in the system.',
    `estimated_cost_amount` DECIMAL(18,2) COMMENT 'Projected total cost in USD to implement all corrective actions, including capital expenditures, operational expenses, consulting fees, and internal labor.',
    `extension_granted_flag` BOOLEAN COMMENT 'Indicates whether the regulatory authority granted an extension to the original target completion date.',
    `extension_requested_flag` BOOLEAN COMMENT 'Indicates whether an extension to the target completion date has been requested from the regulatory authority.',
    `internal_audit_reference` STRING COMMENT 'Reference to the internal audit report or compliance assessment that identified the deficiency requiring corrective action.',
    `last_updated_timestamp` TIMESTAMP COMMENT 'Timestamp when this corrective action plan record was most recently modified or updated.',
    `milestone_count` STRING COMMENT 'Total number of discrete milestones or action items defined within the corrective action plan.',
    `milestones_completed_count` STRING COMMENT 'Number of milestones that have been completed and verified as of the current reporting date.',
    `penalty_amount` DECIMAL(18,2) COMMENT 'Monetary penalty in USD assessed by the regulatory authority for the underlying violation, which may be mitigated or waived based on corrective action plan completion.',
    `penalty_mitigation_flag` BOOLEAN COMMENT 'Indicates whether successful completion of the corrective action plan resulted in reduction or waiver of the assessed penalty.',
    `percent_complete` DECIMAL(18,2) COMMENT 'Overall completion percentage of the corrective action plan, calculated as (milestones_completed_count / milestone_count) * 100.',
    `plan_description` STRING COMMENT 'Detailed narrative describing the corrective actions, remediation steps, process improvements, and controls to be implemented to address the identified deficiency or violation.',
    `plan_number` STRING COMMENT 'Business identifier for the corrective action plan, typically assigned by the regulatory body or internal compliance system.',
    `plan_owner_email` STRING COMMENT 'Email address of the individual or team responsible for day-to-day management and execution of the corrective action plan.',
    `plan_status` STRING COMMENT 'Current lifecycle status of the corrective action plan indicating its stage in the regulatory review and implementation process.',
    `plan_title` STRING COMMENT 'Descriptive title or name of the corrective action plan summarizing the remediation focus.',
    `prudency_review_required_flag` BOOLEAN COMMENT 'Indicates whether the corrective action plan costs are subject to a prudency review by the regulatory commission to determine cost recovery eligibility.',
    `recurrence_risk_level` STRING COMMENT 'Assessment of the likelihood that the underlying violation or non-compliance issue will recur after corrective actions are implemented.',
    `regulatory_authority` STRING COMMENT 'The governing body or regulatory agency that mandated or is overseeing the corrective action plan (e.g., FERC, state PUC, NERC, EPA).',
    `regulatory_filing_reference` STRING COMMENT 'Reference number or identifier of the formal regulatory filing or submission that included or documented this corrective action plan.',
    `responsible_department` STRING COMMENT 'The internal department, business unit, or functional area responsible for executing and completing the corrective action plan.',
    `responsible_officer_name` STRING COMMENT 'Name of the executive or officer accountable for ensuring the corrective action plan is completed and compliance is restored.',
    `revised_completion_date` DATE COMMENT 'Updated target completion date following approval of an extension or plan modification by the regulatory authority.',
    `root_cause_analysis_completed_flag` BOOLEAN COMMENT 'Indicates whether a formal root cause analysis was conducted to identify the underlying systemic issues that led to the violation.',
    `root_cause_summary` STRING COMMENT 'Summary of the root cause analysis findings identifying the fundamental reasons for the non-compliance or deficiency.',
    `severity_level` STRING COMMENT 'Severity classification of the underlying violation or finding as determined by the regulatory authority or internal risk assessment.',
    `submission_date` DATE COMMENT 'Date on which the corrective action plan was formally submitted to the regulatory authority or internal compliance office for review.',
    `target_completion_date` DATE COMMENT 'Planned or mandated date by which all corrective actions must be completed and compliance fully restored.',
    `verification_date` DATE COMMENT 'Date on which the corrective actions were verified as complete and effective by the designated verification authority.',
    `verification_method` STRING COMMENT 'The method or process used to verify completion and effectiveness of corrective actions (e.g., internal audit, third-party assessment, regulatory inspection, self-certification).',
    `verification_status` STRING COMMENT 'Current status of the verification process indicating whether corrective actions have been validated as effective.',
    CONSTRAINT pk_corrective_action_plan PRIMARY KEY(`corrective_action_plan_id`)
) COMMENT 'Master reference table for corrective_action_plan. Referenced by corrective_action_plan_id.';

CREATE OR REPLACE TABLE `power_and_utilities`.`regulatory`.`violation` (
    `violation_id` BIGINT COMMENT 'Primary key for violation',
    `related_violation_id` BIGINT COMMENT 'Self-referencing FK on violation (related_violation_id)',
    `appeal_filed_flag` BOOLEAN COMMENT 'Indicates whether the utility has filed an appeal or contest of the violation finding or penalty.',
    `appeal_outcome` STRING COMMENT 'The final outcome of the appeal process, if an appeal was filed.',
    `asset_id` BIGINT COMMENT 'Identifier of the specific asset or equipment involved in the violation event.',
    `closure_date` DATE COMMENT 'The date on which the regulatory body officially closed the violation case after successful mitigation or penalty resolution.',
    `corrective_action_summary` STRING COMMENT 'Summary of corrective actions taken or planned to prevent recurrence of the violation.',
    `created_timestamp` TIMESTAMP COMMENT 'Timestamp when the violation record was first created in the compliance management system.',
    `customers_affected_count` STRING COMMENT 'Number of customers impacted by the violation event, if applicable.',
    `discovery_date` DATE COMMENT 'The date on which the violation was first identified or discovered by the utility or regulatory body.',
    `docket_number` STRING COMMENT 'Official docket or case number assigned by the regulatory body for tracking the violation proceeding.',
    `facility_id` BIGINT COMMENT 'Identifier of the generation, transmission, or distribution facility where the violation occurred.',
    `impact_description` STRING COMMENT 'Description of the actual or potential impact of the violation on system reliability, safety, environment, or customers.',
    `mitigation_completion_date` DATE COMMENT 'The actual date on which all mitigation activities were completed and verified.',
    `mitigation_due_date` DATE COMMENT 'The deadline by which corrective actions must be completed to remedy the violation.',
    `mitigation_plan_id` BIGINT COMMENT 'Identifier of the formal mitigation plan submitted to address the violation.',
    `notes` STRING COMMENT 'Additional free-form notes or comments related to the violation, mitigation, or regulatory interactions.',
    `notification_date` DATE COMMENT 'The date on which the utility formally notified the regulatory body of the violation.',
    `occurrence_date` DATE COMMENT 'The date on which the violation actually occurred or the non-compliance event took place.',
    `outage_duration_minutes` STRING COMMENT 'Duration of any service outage caused by the violation, measured in minutes.',
    `penalty_amount` DECIMAL(18,2) COMMENT 'Monetary penalty assessed by the regulatory body for the violation, in US dollars.',
    `penalty_currency` STRING COMMENT 'Currency code for the penalty amount. Utility operates in US dollars.',
    `penalty_paid_date` DATE COMMENT 'The date on which the assessed penalty was paid to the regulatory body.',
    `public_disclosure_flag` BOOLEAN COMMENT 'Indicates whether the violation has been publicly disclosed or reported in regulatory filings.',
    `regulatory_body` STRING COMMENT 'The governing authority or regulatory commission that identified or has jurisdiction over the violation.',
    `repeat_violation_flag` BOOLEAN COMMENT 'Indicates whether this is a repeat violation of the same standard within the lookback period.',
    `responsible_department` STRING COMMENT 'The internal department or business unit responsible for the area where the violation occurred.',
    `responsible_employee_id` BIGINT COMMENT 'Identifier of the employee or manager accountable for oversight of the violated standard or process.',
    `root_cause_analysis` STRING COMMENT 'Detailed findings from the root cause analysis investigation conducted to understand why the violation occurred.',
    `root_cause_category` STRING COMMENT 'High-level classification of the underlying root cause of the violation.',
    `self_reported_flag` BOOLEAN COMMENT 'Indicates whether the violation was self-reported by the utility (true) or discovered by the regulatory body (false).',
    `severity_level` STRING COMMENT 'Assessed severity of the violation based on impact to safety, reliability, or compliance.',
    `standard_code` STRING COMMENT 'The specific regulatory standard, rule, or tariff provision that was violated (e.g., NERC CIP-007, EPA CAA Section 111).',
    `standard_description` STRING COMMENT 'Full text description of the regulatory standard or requirement that was violated.',
    `violation_status` STRING COMMENT 'Current lifecycle status of the violation in the compliance management process.',
    `updated_timestamp` TIMESTAMP COMMENT 'Timestamp when the violation record was last modified or updated.',
    `violation_description` STRING COMMENT 'Detailed narrative description of the violation, including circumstances, root cause, and impact.',
    `violation_number` STRING COMMENT 'Externally-known unique violation tracking number assigned by the utility or regulatory body.',
    `violation_type` STRING COMMENT 'Classification of the violation based on the regulatory domain affected.',
    CONSTRAINT pk_violation PRIMARY KEY(`violation_id`)
) COMMENT 'Master reference table for violation. Referenced by violation_id.';

